cd /workspace && python3 << 'PY'
import json
with open('contracts/openapi.contract.json') as f:
    spec = json.load(f)

# Dump each operation's request body and success response in compact form
for path, methods in sorted(spec['paths'].items()):
    for method, op in methods.items():
        if method not in ('get','post','put','patch','delete'):
            continue
        oid = op.get('operationId')
        print(f"\n{'='*80}")
        print(f"{method.upper()} {path} -> {oid}")
        if 'parameters' in op and op['parameters']:
            print("PARAMS:", json.dumps(op['parameters'], indent=2)[:1500])
        if 'requestBody' in op:
            rb = op['requestBody']
            content = rb.get('content',{})
            for ct, body in content.items():
                print(f"REQUEST ({ct}):")
                print(json.dumps(body.get('schema',{}), indent=2)[:3000])
        for code, resp in sorted(op.get('responses',{}).items()):
            if code.startswith('2'):
                content = resp.get('content',{})
                for ct, body in content.items():
                    print(f"RESPONSE {code} ({ct}):")
                    print(json.dumps(body.get('schema',{}), indent=2)[:4000])
            else:
                # just list error codes
                schema = resp.get('content',{}).get('application/json',{}).get('schema',{})
                codes = schema.get('properties',{}).get('code',{}).get('enum',[])
                if codes:
                    print(f"ERROR {code}: {codes}")
                else:
                    print(f"ERROR {code}")
