import json
with open('contracts/openapi.contract.json') as f:
    spec = json.load(f)

# component schemas
print("=== SCHEMAS ===")
for name, schema in sorted(spec['components']['schemas'].items()):
    print(f"\n--- {name} ---")
    print(json.dumps(schema, indent=2)[:2500])

# Get remaining ops that might have been clipped
needed = [
 'confirm_handoff','confirm_laboratory_receipt','create_collection_request','create_connection',
 'create_location','create_sample_type','create_user','decline_assignment','edit_active_plan',
 'stream_realtime_events','ingest_presealed_sample','initiate_handoff','list_role_work',
 'merge_journeys','read_journey_plan','read_operations_state','read_sample_lifecycle',
 'read_sample_state','read_serviceability_snapshot','read_user','record_handling_checkpoint',
 'record_laboratory_exception','record_worker_location','report_disruption','reroute_journey',
 'search_audit_trail','select_active_role','set_connection_status','set_location_function_status'
]
for path, methods in sorted(spec['paths'].items()):
    for method, op in methods.items():
        if method not in ('get','post','put','patch','delete'):
            continue
        oid = op.get('operationId')
        if oid not in needed:
            continue
        print(f"\n{'='*80}")
        print(f"{method.upper()} {path} -> {oid}")
        if 'parameters' in op and op['parameters']:
            print("PARAMS:", json.dumps(op['parameters'])[:800])
        if 'requestBody' in op:
            for ct, body in op['requestBody'].get('content',{}).items():
                print(f"REQUEST:")
                print(json.dumps(body.get('schema',{}), indent=2)[:2500])
        for code, resp in sorted(op.get('responses',{}).items()):
            if str(code).startswith('2'):
                for ct, body in resp.get('content',{}).items():
                    print(f"RESPONSE {code}:")
                    print(json.dumps(body.get('schema',{}), indent=2)[:3000])
