import (
	"context"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"lablogistics/internal/api"
	"lablogistics/internal/db"
	"lablogistics/internal/service"
)

func main() {
	ctx := context.Background()
	databaseURL := getenv("DATABASE_URL", "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable")
	mongoURI := getenv("MONGODB_URI", "mongodb://127.0.0.1:27017/arena")
	addr := getenv("LISTEN_ADDR", "127.0.0.1:8080")
	staticDir := getenv("STATIC_DIR", "/workspace/frontend/dist")
	mapAssets := getenv("MAP_ASSETS", "/opt/arena/map-assets")

	pg, err := db.ConnectPostgres(ctx, databaseURL)
	if err != nil {
		log.Fatalf("postgres: %v", err)
	}
	defer pg.Close()

	mg, err := db.ConnectMongo(ctx, mongoURI)
	if err != nil {
		log.Fatalf("mongo: %v", err)
	}
	defer mg.Disconnect(context.Background())

	store := db.NewStore(pg, mg)
	if err := store.EnsureSchema(ctx); err != nil {
		log.Fatalf("schema: %v", err)
	}

	svc := service.New(store)
	if err := svc.BootstrapAdmin(ctx, os.Getenv("ADMIN_USERNAME"), os.Getenv("ADMIN_PASSWORD")); err != nil {
		log.Fatalf("bootstrap admin: %v", err)
	}
	if err := svc.EnsureDefaultSampleTypes(ctx); err != nil {
		log.Fatalf("sample types: %v", err)
	}
	svc.StartBackground(ctx)

	h := api.NewHandler(svc, staticDir, mapAssets)
	srv := &http.Server{Addr: addr, Handler: h.Router(), ReadHeaderTimeout: 10 * time.Second}
	go func() {
		log.Printf("listening on http://%s", addr)
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("serve: %v", err)
		}
	}()
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop
	shctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	_ = srv.Shutdown(shctx)
}

func getenv(k, d string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return d
}
""")
print("main ok")
'

