w("internal/service/service.go", r'''package service

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"math"
	"sync"
	"time"

	"lablogistics/internal/db"
	"lablogistics/internal/models"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo/options"
	"golang.org/x/crypto/bcrypt"
)

const OfferTimeout = 2 * time.Minute
const DeclinePenalty = 10 * time.Minute

type Service struct {
	store *db.Store
	mu    sync.Mutex
	hub   *EventHub
}

func New(store *db.Store) *Service {
	s := &Service{store: store, hub: NewEventHub()}
	return s
}

func (s *Service) Store() *db.Store { return s.store }
func (s *Service) Hub() *EventHub   { return s.hub }

func (s *Service) StartBackground(ctx context.Context) {
	go s.offerExpiryLoop(ctx)
	go s.ensureServiceabilitySnapshot(ctx)
}

func (s *Service) offerExpiryLoop(ctx context.Context) {
