func (h *EventHub) Unsubscribe(ch chan models.RealtimeEvent) {
	h.mu.Lock()
	delete(h.subs, ch)
	h.mu.Unlock()
	close(ch)
}

func (h *EventHub) Broadcast(ev models.RealtimeEvent) {
	h.mu.RLock()
	defer h.mu.RUnlock()
	for ch, info := range h.subs {
		if ev.Audience != "" && ev.Audience != "all" && ev.Audience != info.role {
			// allow user-specific audience like "user:<id>"
