import (
	"context"
	"encoding/json"
	"strings"
	"time"

	"lablogistics/internal/models"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
)

func (s *Service) BootstrapAdmin(ctx context.Context, username, password string) error {
	if username == "" {
		username = "admin"
	}
	if password == "" {
		password = "admin"
	}
	var n int
	if err := s.store.PG.QueryRow(ctx, `SELECT COUNT(*) FROM users`).Scan(&n); err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	hash, err := hashPassword(password)
	if err != nil {
		return err
	}
	_, err = s.store.PG.Exec(ctx, `
		INSERT INTO users(username, password_hash, full_name, roles, qualifications, certifications, active)
		VALUES($1,$2,'System Administrator', ARRAY['administrator']::text[], '{}', '[]'::jsonb, true)`,
		username, hash)
	return err
}

func (s *Service) Authenticate(ctx context.Context, username, password string) (map[string]any, error) {
	u, err := s.getUserByUsername(ctx, username)
	if err != nil {
		s.Audit(ctx, "", "", "authenticate", "session", "", false, map[string]any{"username": username})
		return nil, models.Unauthorized("invalid_credentials", "invalid username or password")
	}
	if !u.Active || !checkPassword(u.PasswordHash, password) {
		s.Audit(ctx, u.ID.String(), "", "authenticate", "session", "", false, map[string]any{"username": username})
		return nil, models.Unauthorized("invalid_credentials", "invalid username or password")
	}
	token := newToken()
	activeRole := ""
	roleSelected := false
	if len(u.Roles) == 1 {
		activeRole = u.Roles[0]
		roleSelected = true
	}
	_, err = s.store.PG.Exec(ctx, `
		INSERT INTO sessions(token, user_id, active_role, role_selected, expires_at)
		VALUES($1,$2,$3,$4, now() + interval '7 days')`, token, u.ID, activeRole, roleSelected)
	if err != nil {
