func (s *Service) RequireRole(auth *AuthContext, allowed ...string) error {
	if auth == nil {
		return models.Unauthorized("unauthorized", "unauthorized")
	}
	if !auth.RoleSelected || auth.ActiveRole == "" {
		return models.Conflict("role_not_selected", "active role must be selected")
	}
	if auth.ActiveRole == models.RoleAdministrator {
		return nil // admin can do everything
	}
	for _, a := range allowed {
		if auth.ActiveRole == a {
			return nil
		}
		// dispatcher allowed where admin is (already covered)
		if a == models.RoleDispatcher && auth.ActiveRole == models.RoleAdministrator {
			return nil
		}
	}
	// administrator is also dispatcher
	for _, a := range allowed {
		if a == models.RoleDispatcher && auth.ActiveRole == models.RoleAdministrator {
			return nil
		}
		if a == models.RoleAdministrator && auth.ActiveRole == models.RoleAdministrator {
			return nil
		}
	}
	return models.Forbidden("forbidden", "insufficient role")
}

