	for _, r := range roles {
		if !models.IsValidRole(r) {
			return nil, models.BadRequest("invalid_json", "invalid role")
		}
	}
	active, _ := body["active"].(bool)
	quals := toStringSlice(body["qualifications"])
	if body["qualifications"] == nil {
		quals = u.Qualifications
	}
	certs := u.Certifications
	if body["certifications"] != nil {
		certs = parseCerts(body["certifications"])
	}
	certJSON, _ := json.Marshal(certs)
