			return nil, models.BadRequest("invalid_json", "invalid assignedLocationId")
		}
		assigned = id
	}
	certJSON, _ := json.Marshal(certs)
	var id uuid.UUID
	err = s.store.PG.QueryRow(ctx, `
		INSERT INTO users(username,password_hash,email,full_name,phone,roles,qualifications,certifications,active,assigned_location_id)
		VALUES($1,$2,$3,$4,$5,$6,$7,$8::jsonb,$9,$10) RETURNING id`,
		username, hash, email, fullName, phone, roles, quals, certJSON, active, assigned,
	).Scan(&id)
	if err != nil {
		if strings.Contains(err.Error(), "unique") {
			return nil, models.Conflict("concurrent_conflict", "username exists")
		}
		return nil, models.Internal(err.Error())
	}
	u, _ := s.getUserByID(ctx, id)
	s.Audit(ctx, auth.User.ID.String(), auth.ActiveRole, "create_user", "user", id.String(), true, map[string]any{"username": username})
	return userPublic(u), nil
}

func (s *Service) UpdateUserAccess(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleAdministrator); err != nil {
		return nil, err
	}
	uidStr, _ := body["userId"].(string)
	uid, err := uuid.Parse(uidStr)
	if err != nil {
		return nil, models.BadRequest("invalid_json", "invalid userId")
	}
	u, err := s.getUserByID(ctx, uid)
	if err != nil {
		return nil, err
	}
	roles := toStringSlice(body["roles"])
	for _, r := range roles {
		if !models.IsValidRole(r) {
			return nil, models.BadRequest("invalid_json", "invalid role")
		}
	}
	active, _ := body["active"].(bool)
	quals := toStringSlice(body["qualifications"])
	if body["qualifications"] == nil {
		quals = u.Qualifications
	}
	certs := u.Certifications
	if body["certifications"] != nil {
		certs = parseCerts(body["certifications"])
	}
	certJSON, _ := json.Marshal(certs)
	var assigned any = u.AssignedLocationID
	if v, ok := body["assignedLocationId"].(string); ok {
		if v == "" {
			assigned = nil
		} else {
			id, err := uuid.Parse(v)
			if err != nil {
				return nil, models.BadRequest("invalid_json", "invalid assignedLocationId")
			}
			assigned = id
		}
	}
	_, err = s.store.PG.Exec(ctx, `
		UPDATE users SET roles=$1, qualifications=$2, certifications=$3::jsonb, active=$4, assigned_location_id=$5, updated_at=now()
		WHERE id=$6`, roles, quals, certJSON, active, assigned, uid)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	u, _ = s.getUserByID(ctx, uid)
	s.Audit(ctx, auth.User.ID.String(), auth.ActiveRole, "update_user_access", "user", uid.String(), true, nil)
	return userPublic(u), nil
}

func (s *Service) ReadUser(ctx context.Context, auth *AuthContext, userID uuid.UUID) (map[string]any, error) {
	if auth == nil {
		return nil, models.Unauthorized("unauthorized", "unauthorized")
	}
	// self or admin/dispatcher
	if auth.User.ID != userID {
		if err := s.RequireAdminOrDispatcher(auth); err != nil {
			if auth.User.ID != userID {
				return nil, models.Forbidden("forbidden", "forbidden")
			}
		}
	}
	u, err := s.getUserByID(ctx, userID)
	if err != nil {
		return nil, err
	}
	return userPublic(u), nil
}

func toStringSlice(v any) []string {
	if v == nil {
		return []string{}
	}
	arr, ok := v.([]any)
	if !ok {
		if ss, ok := v.([]string); ok {
			return ss
		}
		return []string{}
	}
	out := make([]string, 0, len(arr))
	for _, x := range arr {
		if s, ok := x.(string); ok {
			out = append(out, s)
		}
	}
	return out
}

func parseCerts(v any) []models.Certification {
	out := []models.Certification{}
	if v == nil {
		return out
	}
	arr, ok := v.([]any)
	if !ok {
		return out
	}
	for _, item := range arr {
		m, ok := item.(map[string]any)
		if !ok {
			continue
		}
		c := models.Certification{Code: str(m["code"]), Active: toBool(m["active"])}
		if c.Code == "" {
			continue
		}
		if ea, ok := m["expiresAt"].(string); ok && ea != "" {
			if t, err := time.Parse(time.RFC3339Nano, ea); err == nil {
				c.ExpiresAt = &t
			} else if t, err := time.Parse(time.RFC3339, ea); err == nil {
				c.ExpiresAt = &t
			}
		}
		out = append(out, c)
	}
	return out
}

func (s *Service) SetWorkerAvailability(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleAdministrator, models.RoleDispatcher,
		models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam); err != nil {
		return nil, err
	}
	wid, err := uuid.Parse(str(body["workerId"]))
	if err != nil {
		return nil, models.BadRequest("invalid_json", "invalid workerId")
	}
	if auth.ActiveRole != models.RoleAdministrator && auth.ActiveRole != models.RoleDispatcher && auth.User.ID != wid {
		return nil, models.Forbidden("forbidden", "can only set own availability")
	}
	available, ok := body["available"].(bool)
	if !ok {
		return nil, models.BadRequest("invalid_json", "available required")
	}
	capF, ok := body["capacityUnits"].(float64)
	if !ok || capF < 0 {
		return nil, models.BadRequest("invalid_capacity", "invalid capacity")
	}
	cap := int(capF)
	// check reserved
	var reserved int
	_ = s.store.PG.QueryRow(ctx, `
		SELECT COALESCE(SUM(units),0) FROM capacity_reservations WHERE resource_type='worker' AND resource_id=$1 AND active`, wid).Scan(&reserved)
	if cap < reserved {
		return nil, models.Conflict("capacity_reserved", "capacity below reserved")
