	ct, err := s.store.PG.Exec(ctx, `UPDATE users SET available=$1, capacity_units=$2, updated_at=now() WHERE id=$3`, available, cap, wid)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	if ct.RowsAffected() == 0 {
		return nil, models.NotFound("not_found", "worker not found")
	}
	return map[string]any{"workerId": wid.String(), "available": available, "capacityUnits": cap}, nil
}
''')
