type scannable interface {
	Scan(dest ...any) error
}

func scanUser(row scannable) (*models.User, error) {
	var u models.User
	var roles, quals []string
	var certJSON []byte
	var assigned *uuid.UUID
	err := row.Scan(&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone,
		&roles, &quals, &certJSON, &u.Active, &assigned, &u.Available, &u.CapacityUnits, &u.AssignmentCount,
		&u.DeclinePenaltyUntil, &u.LatestLat, &u.LatestLng, &u.LocationRecordedAt)
	if err == pgx.ErrNoRows {
		return nil, models.NotFound("not_found", "user not found")
	}
	if err != nil {
		return nil, err
	}
	u.Roles = roles
