func (s *Service) BootstrapAdmin(ctx context.Context, username, password string) error {
	if username == "" {
		username = "admin"
	}
	if password == "" {
		password = "admin"
	}
	var n int
	if err := s.store.PG.QueryRow(ctx, `SELECT COUNT(*) FROM users`).Scan(&n); err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	hash, err := hashPassword(password)
	if err != nil {
		return err
	}
	_, err = s.store.PG.Exec(ctx, `
		INSERT INTO users(username, password_hash, full_name, roles, qualifications, certifications, active)
		VALUES($1,$2,'System Administrator', ARRAY['administrator']::text[], '{}', '[]'::jsonb, true)`,
		username, hash)
	return err
}

func (s *Service) Authenticate(ctx context.Context, username, password string) (map[string]any, error) {
	u, err := s.getUserByUsername(ctx, username)
	if err != nil {
		s.Audit(ctx, "", "", "authenticate", "session", "", false, map[string]any{"username": username})
		return nil, models.Unauthorized("invalid_credentials", "invalid username or password")
	}
	if !u.Active || !checkPassword(u.PasswordHash, password) {
		s.Audit(ctx, u.ID.String(), "", "authenticate", "session", "", false, map[string]any{"username": username})
		return nil, models.Unauthorized("invalid_credentials", "invalid username or password")
	}
	token := newToken()
	activeRole := ""
	roleSelected := false
	if len(u.Roles) == 1 {
		activeRole = u.Roles[0]
		roleSelected = true
	}
	_, err = s.store.PG.Exec(ctx, `
		INSERT INTO sessions(token, user_id, active_role, role_selected, expires_at)
		VALUES($1,$2,$3,$4, now() + interval '7 days')`, token, u.ID, activeRole, roleSelected)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	s.Audit(ctx, u.ID.String(), activeRole, "authenticate", "session", token[:8], true, map[string]any{"username": username})
	return map[string]any{
		"sessionToken": token,
		"userId":       u.ID.String(),
		"roles":        u.Roles,
		"activeRole":   activeRole,
	}, nil
}

type AuthContext struct {
	User         *models.User
	SessionToken string
	ActiveRole   string
	RoleSelected bool
}

func (s *Service) ResolveSession(ctx context.Context, token string) (*AuthContext, error) {
	if token == "" {
		return nil, models.Unauthorized("unauthorized", "missing token")
	}
	var userID uuid.UUID
	var activeRole string
	var roleSelected bool
	var expires time.Time
	err := s.store.PG.QueryRow(ctx, `
		SELECT user_id, active_role, role_selected, expires_at FROM sessions WHERE token=$1`, token,
	).Scan(&userID, &activeRole, &roleSelected, &expires)
	if err == pgx.ErrNoRows {
		return nil, models.Unauthorized("unauthorized", "invalid session")
	}
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	if time.Now().After(expires) {
		return nil, models.Unauthorized("unauthorized", "session expired")
	}
	u, err := s.getUserByID(ctx, userID)
	if err != nil || !u.Active {
		return nil, models.Unauthorized("unauthorized", "user inactive")
	}
	return &AuthContext{User: u, SessionToken: token, ActiveRole: activeRole, RoleSelected: roleSelected}, nil
}

func (s *Service) RequireRole(auth *AuthContext, allowed ...string) error {
	if auth == nil {
		return models.Unauthorized("unauthorized", "unauthorized")
	}
	if !auth.RoleSelected || auth.ActiveRole == "" {
		return models.Conflict("role_not_selected", "active role must be selected")
	}
	if auth.ActiveRole == models.RoleAdministrator {
		return nil // admin can do everything
	}
	for _, a := range allowed {
		if auth.ActiveRole == a {
			return nil
		}
		// dispatcher allowed where admin is (already covered)
		if a == models.RoleDispatcher && auth.ActiveRole == models.RoleAdministrator {
			return nil
		}
	}
	// administrator is also dispatcher
	for _, a := range allowed {
		if a == models.RoleDispatcher && auth.ActiveRole == models.RoleAdministrator {
			return nil
		}
		if a == models.RoleAdministrator && auth.ActiveRole == models.RoleAdministrator {
			return nil
		}
	}
	return models.Forbidden("forbidden", "insufficient role")
}

func (s *Service) RequireAdminOrDispatcher(auth *AuthContext) error {
	return s.RequireRole(auth, models.RoleAdministrator, models.RoleDispatcher)
}

func (s *Service) SelectActiveRole(ctx context.Context, auth *AuthContext, role string) (map[string]any, error) {
	if !models.IsValidRole(role) {
		return nil, models.BadRequest("invalid_json", "invalid role")
	}
	found := false
	for _, r := range auth.User.Roles {
		if r == role {
			found = true
			break
		}
	}
	if !found {
		return nil, models.Forbidden("forbidden", "role not assigned")
	}
	_, err := s.store.PG.Exec(ctx, `UPDATE sessions SET active_role=$1, role_selected=true WHERE token=$2`, role, auth.SessionToken)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	s.Audit(ctx, auth.User.ID.String(), role, "select_active_role", "session", auth.SessionToken[:8], true, map[string]any{"role": role})
	return map[string]any{"activeRole": role, "roles": auth.User.Roles}, nil
}

func (s *Service) getUserByUsername(ctx context.Context, username string) (*models.User, error) {
	row := s.store.PG.QueryRow(ctx, `
		SELECT id, username, password_hash, email, full_name, phone, roles, qualifications, certifications,
		       active, assigned_location_id, available, capacity_units, assignment_count,
		       decline_penalty_until, latest_lat, latest_lng, location_recorded_at
		FROM users WHERE username=$1`, username)
	return scanUser(row)
}

func (s *Service) getUserByID(ctx context.Context, id uuid.UUID) (*models.User, error) {
	row := s.store.PG.QueryRow(ctx, `
		SELECT id, username, password_hash, email, full_name, phone, roles, qualifications, certifications,
		       active, assigned_location_id, available, capacity_units, assignment_count,
		       decline_penalty_until, latest_lat, latest_lng, location_recorded_at
		FROM users WHERE id=$1`, id)
	return scanUser(row)
}

type scannable interface {
	Scan(dest ...any) error
}

func scanUser(row scannable) (*models.User, error) {
	var u models.User
	var roles, quals []string
	var certJSON []byte
	var assigned *uuid.UUID
	err := row.Scan(&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone,
		&roles, &quals, &certJSON, &u.Active, &assigned, &u.Available, &u.CapacityUnits, &u.AssignmentCount,
		&u.DeclinePenaltyUntil, &u.LatestLat, &u.LatestLng, &u.LocationRecordedAt)
	if err == pgx.ErrNoRows {
		return nil, models.NotFound("not_found", "user not found")
	}
	if err != nil {
		return nil, err
	}
	u.Roles = roles
	if u.Roles == nil {
		u.Roles = []string{}
	}
	u.Qualifications = quals
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}
	_ = json.Unmarshal(certJSON, &u.Certifications)
	if u.Certifications == nil {
		u.Certifications = []models.Certification{}
	}
	u.AssignedLocationID = assigned
	return &u, nil
}

func userPublic(u *models.User) map[string]any {
	m := map[string]any{
		"userId":         u.ID.String(),
		"username":       u.Username,
		"roles":          u.Roles,
		"qualifications": u.Qualifications,
		"certifications": u.Certifications,
		"active":         u.Active,
	}
	if u.Email != "" {
		m["email"] = u.Email
	}
	if u.FullName != "" {
		m["fullName"] = u.FullName
	}
	if u.Phone != "" {
		m["phone"] = u.Phone
	}
	return m
}

func (s *Service) CreateUser(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleAdministrator); err != nil {
		return nil, err
	}
	username, _ := body["username"].(string)
	password, _ := body["initialPassword"].(string)
	if username == "" || password == "" {
		return nil, models.BadRequest("invalid_json", "username and password required")
	}
	roles := toStringSlice(body["roles"])
	if len(roles) == 0 {
		return nil, models.BadRequest("invalid_json", "roles required")
	}
	for _, r := range roles {
		if !models.IsValidRole(r) {
			return nil, models.BadRequest("invalid_json", "invalid role")
		}
	}
	active, _ := body["active"].(bool)
	if _, ok := body["active"]; !ok {
		active = true
	}
	hash, err := hashPassword(password)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	quals := toStringSlice(body["qualifications"])
	certs := parseCerts(body["certifications"])
	email, _ := body["email"].(string)
	fullName, _ := body["fullName"].(string)
	phone, _ := body["phone"].(string)
	var assigned any
	if v, ok := body["assignedLocationId"].(string); ok && v != "" {
		id, err := uuid.Parse(v)
		if err != nil {
			return nil, models.BadRequest("invalid_json", "invalid assignedLocationId")
		}
		assigned = id
	}
	certJSON, _ := json.Marshal(certs)
	var id uuid.UUID
	err = s.store.PG.QueryRow(ctx, `
		INSERT INTO users(username,password_hash,email,full_name,phone,roles,qualifications,certifications,active,assigned_location_id)
		VALUES($1,$2,$3,$4,$5,$6,$7,$8::jsonb,$9,$10) RETURNING id`,
		username, hash, email, fullName, phone, roles, quals, certJSON, active, assigned,
	).Scan(&id)
	if err != nil {
		if strings.Contains(err.Error(), "unique") {
			return nil, models.Conflict("concurrent_conflict", "username exists")
		}
		return nil, models.Internal(err.Error())
	}
	u, _ := s.getUserByID(ctx, id)
	s.Audit(ctx, auth.User.ID.String(), auth.ActiveRole, "create_user", "user", id.String(), true, map[string]any{"username": username})
	return userPublic(u), nil
}

func (s *Service) UpdateUserAccess(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleAdministrator); err != nil {
		return nil, err
	}
	uidStr, _ := body["userId"].(string)
	uid, err := uuid.Parse(uidStr)
	if err != nil {
		return nil, models.BadRequest("invalid_json", "invalid userId")
	}
	u, err := s.getUserByID(ctx, uid)
	if err != nil {
		return nil, err
	}
	roles := toStringSlice(body["roles"])
	for _, r := range roles {
		if !models.IsValidRole(r) {
			return nil, models.BadRequest("invalid_json", "invalid role")
		}
	}
	active, _ := body["active"].(bool)
	quals := toStringSlice(body["qualifications"])
	if body["qualifications"] == nil {
		quals = u.Qualifications
	}
	certs := u.Certifications
	if body["certifications"] != nil {
		certs = parseCerts(body["certifications"])
	}
	certJSON, _ := json.Marshal(certs)
	var assigned any = u.AssignedLocationID
	if v, ok := body["assignedLocationId"].(string); ok {
		if v == "" {
			assigned = nil
		} else {
			id, err := uuid.Parse(v)
			if err != nil {
				return nil, models.BadRequest("invalid_json", "invalid assignedLocationId")
			}
			assigned = id
		}
	}
	_, err = s.store.PG.Exec(ctx, `
		UPDATE users SET roles=$1, qualifications=$2, certifications=$3::jsonb, active=$4, assigned_location_id=$5, updated_at=now()
		WHERE id=$6`, roles, quals, certJSON, active, assigned, uid)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	u, _ = s.getUserByID(ctx, uid)
	s.Audit(ctx, auth.User.ID.String(), auth.ActiveRole, "update_user_access", "user", uid.String(), true, nil)
	return userPublic(u), nil
}

func (s *Service) ReadUser(ctx context.Context, auth *AuthContext, userID uuid.UUID) (map[string]any, error) {
	if auth == nil {
		return nil, models.Unauthorized("unauthorized", "unauthorized")
	}
	// self or admin/dispatcher
	if auth.User.ID != userID {
		if err := s.RequireAdminOrDispatcher(auth); err != nil {
			if auth.User.ID != userID {
				return nil, models.Forbidden("forbidden", "forbidden")
			}
		}
	}
	u, err := s.getUserByID(ctx, userID)
	if err != nil {
		return nil, err
	}
	return userPublic(u), nil
}

func toStringSlice(v any) []string {
	if v == nil {
		return []string{}
	}
	arr, ok := v.([]any)
	if !ok {
		if ss, ok := v.([]string); ok {
			return ss
		}
		return []string{}
	}
	out := make([]string, 0, len(arr))
	for _, x := range arr {
		if s, ok := x.(string); ok {
			out = append(out, s)
		}
	}
	return out
}

func parseCerts(v any) []models.Certification {
	out := []models.Certification{}
	if v == nil {
		return out
	}
	arr, ok := v.([]any)
	if !ok {
		return out
	}
	for _, item := range arr {
		m, ok := item.(map[string]any)
		if !ok {
			continue
		}
		c := models.Certification{Code: str(m["code"]), Active: toBool(m["active"])}
		if c.Code == "" {
			continue
		}
		if ea, ok := m["expiresAt"].(string); ok && ea != "" {
			if t, err := time.Parse(time.RFC3339Nano, ea); err == nil {
				c.ExpiresAt = &t
			} else if t, err := time.Parse(time.RFC3339, ea); err == nil {
				c.ExpiresAt = &t
			}
		}
		out = append(out, c)
	}
	return out
}

func (s *Service) SetWorkerAvailability(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleAdministrator, models.RoleDispatcher,
		models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam); err != nil {
		return nil, err
	}
	wid, err := uuid.Parse(str(body["workerId"]))
	if err != nil {
		return nil, models.BadRequest("invalid_json", "invalid workerId")
	}
	if auth.ActiveRole != models.RoleAdministrator && auth.ActiveRole != models.RoleDispatcher && auth.User.ID != wid {
		return nil, models.Forbidden("forbidden", "can only set own availability")
	}
	available, ok := body["available"].(bool)
	if !ok {
		return nil, models.BadRequest("invalid_json", "available required")
	}
	capF, ok := body["capacityUnits"].(float64)
	if !ok || capF < 0 {
		return nil, models.BadRequest("invalid_capacity", "invalid capacity")
	}
	cap := int(capF)
	// check reserved
	var reserved int
	_ = s.store.PG.QueryRow(ctx, `
		SELECT COALESCE(SUM(units),0) FROM capacity_reservations WHERE resource_type='worker' AND resource_id=$1 AND active`, wid).Scan(&reserved)
	if cap < reserved {
		return nil, models.Conflict("capacity_reserved", "capacity below reserved")
	}
	ct, err := s.store.PG.Exec(ctx, `UPDATE users SET available=$1, capacity_units=$2, updated_at=now() WHERE id=$3`, available, cap, wid)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	if ct.RowsAffected() == 0 {
		return nil, models.NotFound("not_found", "worker not found")
	}
	return map[string]any{"workerId": wid.String(), "available": available, "capacityUnits": cap}, nil
}
''')
