func (s *Service) bumpNetwork(ctx context.Context) {
	_, _ = s.store.PG.Exec(ctx, `UPDATE network_meta SET revision = revision + 1 WHERE id=1`)
	go s.recomputeServiceability(context.Background())
}

func (s *Service) EnsureDefaultSampleTypes(ctx context.Context) error {
	defaults := []struct {
		name, container, qual string
		tmin, tmax           float64
		cooled, batch        bool
	}{
		{"Amber", "standard", "Amber", 2, 25, false, true},
		{"Indigo", "indigo", "Indigo", 2, 25, false, true},
		{"Frost", "cooled", "Frost", 2, 8, true, true},
		{"Pulse", "express", "Pulse", 2, 25, false, false},
	}
	var ids = map[string]uuid.UUID{}
	for _, d := range defaults {
		var id uuid.UUID
		err := s.store.PG.QueryRow(ctx, `SELECT id FROM sample_types WHERE name=$1`, d.name).Scan(&id)
		if err == pgx.ErrNoRows {
			err = s.store.PG.QueryRow(ctx, `
				INSERT INTO sample_types(name, qualified_collector_required, required_qualification, container_type,
					temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed)
				VALUES($1,true,$2,$3,$4,$5,$6,$7) RETURNING id`,
				d.name, d.qual, d.container, d.tmin, d.tmax, d.cooled, d.batch).Scan(&id)
			if err != nil {
				return err
			}
		} else if err != nil {
			return err
		}
		ids[d.name] = id
	}
	// Indigo incompatible with Amber
	if amber, ok := ids["Amber"]; ok {
		if indigo, ok := ids["Indigo"]; ok {
			_, _ = s.store.PG.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types = ARRAY[$1]::uuid[] WHERE id=$2`, amber, indigo)
			_, _ = s.store.PG.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types = ARRAY[$1]::uuid[] WHERE id=$2`, indigo, amber)
		}
	}
	return s.ensureServiceabilitySnapshot(ctx)
}

func (s *Service) CreateSampleType(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleAdministrator); err != nil {
		return nil, err
	}
	name := str(body["name"])
	container := str(body["containerType"])
	if name == "" || container == "" {
		return nil, models.BadRequest("invalid_handling_rule", "name and container required")
	}
	tmin, ok1 := toFloat(body["temperatureMinC"])
	tmax, ok2 := toFloat(body["temperatureMaxC"])
	if !ok1 || !ok2 {
		return nil, models.BadRequest("invalid_handling_rule", "temperature required")
	}
	qcr := true
	if v, ok := body["qualifiedCollectorRequired"].(bool); ok {
		qcr = v
	}
	rq := str(body["requiredQualification"])
	if rq == "" {
		rq = name
	}
	cooled, _ := body["requiresCooledRoute"].(bool)
	batch := true
	if v, ok := body["batchingAllowed"].(bool); ok {
		batch = v
	}
	incomp := toUUIDSlice(body["incompatibleSampleTypes"])
	var id uuid.UUID
	err := s.store.PG.QueryRow(ctx, `
		INSERT INTO sample_types(name,qualified_collector_required,required_qualification,container_type,
			temperature_min_c,temperature_max_c,incompatible_sample_types,requires_cooled_route,batching_allowed)
		VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING id`,
		name, qcr, rq, container, tmin, tmax, incomp, cooled, batch).Scan(&id)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	st, _ := s.getSampleType(ctx, id)
	s.Audit(ctx, auth.User.ID.String(), auth.ActiveRole, "create_sample_type", "sample_type", id.String(), true, nil)
	s.bumpNetwork(ctx)
	return sampleTypePublic(st), nil
}

func (s *Service) UpdateSampleType(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleAdministrator); err != nil {
		return nil, err
	}
	id, err := uuid.Parse(str(body["sampleTypeId"]))
	if err != nil {
		return nil, models.BadRequest("invalid_json", "invalid sampleTypeId")
	}
	st, err := s.getSampleType(ctx, id)
	if err != nil {
		return nil, err
	}
	container := str(body["containerType"])
	tmin, ok1 := toFloat(body["temperatureMinC"])
	tmax, ok2 := toFloat(body["temperatureMaxC"])
	if container == "" || !ok1 || !ok2 {
		return nil, models.BadRequest("invalid_handling_rule", "invalid handling")
	}
	qcr := st.QualifiedCollectorRequired
	if v, ok := body["qualifiedCollectorRequired"].(bool); ok {
		qcr = v
	}
	rq := st.RequiredQualification
	if v := str(body["requiredQualification"]); v != "" {
		rq = v
	}
	cooled := st.RequiresCooledRoute
	if v, ok := body["requiresCooledRoute"].(bool); ok {
		cooled = v
	}
	batch := st.BatchingAllowed
	if v, ok := body["batchingAllowed"].(bool); ok {
		batch = v
	}
	incomp := st.IncompatibleSampleTypes
	if body["incompatibleSampleTypes"] != nil {
		incomp = toUUIDSlice(body["incompatibleSampleTypes"])
	}
	_, err = s.store.PG.Exec(ctx, `
		UPDATE sample_types SET qualified_collector_required=$1, required_qualification=$2, container_type=$3,
		temperature_min_c=$4, temperature_max_c=$5, incompatible_sample_types=$6, requires_cooled_route=$7, batching_allowed=$8
		WHERE id=$9`, qcr, rq, container, tmin, tmax, incomp, cooled, batch, id)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	st, _ = s.getSampleType(ctx, id)
	s.Audit(ctx, auth.User.ID.String(), auth.ActiveRole, "update_sample_type", "sample_type", id.String(), true, nil)
	s.bumpNetwork(ctx)
	return sampleTypePublic(st), nil
}

func sampleTypePublic(st *models.SampleType) map[string]any {
	incomp := make([]string, 0, len(st.IncompatibleSampleTypes))
	for _, id := range st.IncompatibleSampleTypes {
		incomp = append(incomp, id.String())
	}
	return map[string]any{
		"sampleTypeId":                 st.ID.String(),
		"name":                         st.Name,
		"qualifiedCollectorRequired":   st.QualifiedCollectorRequired,
		"requiredQualification":        st.RequiredQualification,
		"containerType":                st.ContainerType,
		"temperatureMinC":              st.TemperatureMinC,
		"temperatureMaxC":              st.TemperatureMaxC,
		"incompatibleSampleTypes":      incomp,
		"requiresCooledRoute":          st.RequiresCooledRoute,
		"batchingAllowed":              st.BatchingAllowed,
	}
}

func (s *Service) getSampleType(ctx context.Context, id uuid.UUID) (*models.SampleType, error) {
	var st models.SampleType
	var incomp []uuid.UUID
	err := s.store.PG.QueryRow(ctx, `
		SELECT id,name,qualified_collector_required,required_qualification,container_type,
		temperature_min_c,temperature_max_c,incompatible_sample_types,requires_cooled_route,batching_allowed
		FROM sample_types WHERE id=$1`, id).Scan(
		&st.ID, &st.Name, &st.QualifiedCollectorRequired, &st.RequiredQualification, &st.ContainerType,
		&st.TemperatureMinC, &st.TemperatureMaxC, &incomp, &st.RequiresCooledRoute, &st.BatchingAllowed)
	if err == pgx.ErrNoRows {
		return nil, models.NotFound("not_found", "sample type not found")
	}
	if err != nil {
		return nil, err
	}
	st.IncompatibleSampleTypes = incomp
