		} else if err != nil {
			return err
		}
		ids[d.name] = id
	}
	// Indigo incompatible with Amber
	if amber, ok := ids["Amber"]; ok {
		if indigo, ok := ids["Indigo"]; ok {
			_, _ = s.store.PG.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types = ARRAY[$1]::uuid[] WHERE id=$2`, amber, indigo)
			_, _ = s.store.PG.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types = ARRAY[$1]::uuid[] WHERE id=$2`, indigo, amber)
		}
	}
	return s.ensureServiceabilitySnapshot(ctx)
}

