func (s *Service) listLocations(ctx context.Context) ([]models.Location, error) {
	rows, err := s.store.PG.Query(ctx, `
		SELECT id,name,latitude,longitude,coverage_km,handling_minutes,active,
		fn_collection_point,fn_transfer_point,fn_hub,fn_laboratory,
		capacity_units,reserved_units,cooled_capacity_units,cooled_reserved_units FROM locations`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []models.Location
	for rows.Next() {
		var l models.Location
		if err := rows.Scan(&l.ID, &l.Name, &l.Coordinate.Latitude, &l.Coordinate.Longitude, &l.CoverageKm, &l.HandlingMinutes, &l.Active,
			&l.Functions.CollectionPoint, &l.Functions.TransferPoint, &l.Functions.Hub, &l.Functions.Laboratory,
			&l.CapacityUnits, &l.ReservedUnits, &l.CooledCapacityUnits, &l.CooledReservedUnits); err != nil {
			return nil, err
		}
		out = append(out, l)
	}
	return out, nil
}

