func (s *Service) EnsureDefaultSampleTypes(ctx context.Context) error {
	defaults := []struct {
		name, container, qual string
		tmin, tmax           float64
		cooled, batch        bool
	}{
		{"Amber", "standard", "Amber", 2, 25, false, true},
		{"Indigo", "indigo", "Indigo", 2, 25, false, true},
		{"Frost", "cooled", "Frost", 2, 8, true, true},
		{"Pulse", "express", "Pulse", 2, 25, false, false},
	}
	var ids = map[string]uuid.UUID{}
	for _, d := range defaults {
		var id uuid.UUID
		err := s.store.PG.QueryRow(ctx, `SELECT id FROM sample_types WHERE name=$1`, d.name).Scan(&id)
		if err == pgx.ErrNoRows {
			err = s.store.PG.QueryRow(ctx, `
				INSERT INTO sample_types(name, qualified_collector_required, required_qualification, container_type,
					temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed)
				VALUES($1,true,$2,$3,$4,$5,$6,$7) RETURNING id`,
				d.name, d.qual, d.container, d.tmin, d.tmax, d.cooled, d.batch).Scan(&id)
			if err != nil {
				return err
			}
		} else if err != nil {
			return err
		}
		ids[d.name] = id
	}
	// Indigo incompatible with Amber
	if amber, ok := ids["Amber"]; ok {
		if indigo, ok := ids["Indigo"]; ok {
			_, _ = s.store.PG.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types = ARRAY[$1]::uuid[] WHERE id=$2`, amber, indigo)
			_, _ = s.store.PG.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types = ARRAY[$1]::uuid[] WHERE id=$2`, indigo, amber)
		}
	}
	return s.ensureServiceabilitySnapshot(ctx)
}

func (s *Service) CreateSampleType(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleAdministrator); err != nil {
		return nil, err
	}
	name := str(body["name"])
	container := str(body["containerType"])
	if name == "" || container == "" {
		return nil, models.BadRequest("invalid_handling_rule", "name and container required")
	}
	tmin, ok1 := toFloat(body["temperatureMinC"])
	tmax, ok2 := toFloat(body["temperatureMaxC"])
	if !ok1 || !ok2 {
		return nil, models.BadRequest("invalid_handling_rule", "temperature required")
	}
	qcr := true
	if v, ok := body["qualifiedCollectorRequired"].(bool); ok {
		qcr = v
	}
	rq := str(body["requiredQualification"])
	if rq == "" {
		rq = name
	}
	cooled, _ := body["requiresCooledRoute"].(bool)
	batch := true
	if v, ok := body["batchingAllowed"].(bool); ok {
		batch = v
	}
	incomp := toUUIDSlice(body["incompatibleSampleTypes"])
	var id uuid.UUID
	err := s.store.PG.QueryRow(ctx, `
		INSERT INTO sample_types(name,qualified_collector_required,required_qualification,container_type,
			temperature_min_c,temperature_max_c,incompatible_sample_types,requires_cooled_route,batching_allowed)
		VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING id`,
		name, qcr, rq, container, tmin, tmax, incomp, cooled, batch).Scan(&id)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	st, _ := s.getSampleType(ctx, id)
	s.Audit(ctx, auth.User.ID.String(), auth.ActiveRole, "create_sample_type", "sample_type", id.String(), true, nil)
