	}
	s.bumpNetwork(ctx)
	s.Audit(ctx, auth.User.ID.String(), auth.ActiveRole, "create_connection", "connection", id.String(), true, nil)
	return map[string]any{
		"connectionId":   id.String(),
		"fromLocationId": fromID.String(),
		"toLocationId":   toID.String(),
		"travelMinutes":  int(travel),
