	active, ok := body["active"].(bool)
	if !ok {
		return nil, models.BadRequest("invalid_json", "active required")
	}
	ct, err := s.store.PG.Exec(ctx, `UPDATE connections SET active=$1 WHERE id=$2`, active, id)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	if ct.RowsAffected() == 0 {
		return nil, models.NotFound("not_found", "not found")
	}
	s.bumpNetwork(ctx)
	return map[string]any{"connectionId": id.String(), "active": active}, nil
}

func (s *Service) ConfigureCapacity(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleAdministrator, models.RoleDispatcher, models.RoleNodeHandler, models.RoleLaboratoryTeam); err != nil {
		return nil, err
	}
	rid, err := uuid.Parse(str(body["resourceId"]))
	if err != nil {
		return nil, models.BadRequest("invalid_json", "invalid resourceId")
	}
	capF, ok := toFloat(body["capacityUnits"])
	if !ok || capF < 0 {
		return nil, models.BadRequest("invalid_capacity", "invalid capacity")
	}
	cooled := 0.0
	if v, ok := toFloat(body["cooledCapacityUnits"]); ok {
		if v < 0 {
			return nil, models.BadRequest("invalid_capacity", "invalid cooled")
		}
		cooled = v
	}
	cap, ccap := int(capF), int(cooled)

	// try location
	var reserved, cooledReserved int
	err = s.store.PG.QueryRow(ctx, `SELECT reserved_units, cooled_reserved_units FROM locations WHERE id=$1`, rid).Scan(&reserved, &cooledReserved)
	if err == nil {
		if auth.ActiveRole == models.RoleNodeHandler || auth.ActiveRole == models.RoleLaboratoryTeam {
			if auth.User.AssignedLocationID == nil || *auth.User.AssignedLocationID != rid {
				return nil, models.Forbidden("forbidden", "not assigned to this location")
			}
		}
		if cap < reserved || ccap < cooledReserved {
			return nil, models.Conflict("capacity_reserved", "below reserved")
		}
		_, err = s.store.PG.Exec(ctx, `UPDATE locations SET capacity_units=$1, cooled_capacity_units=$2, updated_at=now() WHERE id=$3`, cap, ccap, rid)
		if err != nil {
			return nil, models.Internal(err.Error())
		}
		s.bumpNetwork(ctx)
		return map[string]any{"resourceId": rid.String(), "capacityUnits": cap, "cooledCapacityUnits": ccap}, nil
	}
	// try connection
	err = s.store.PG.QueryRow(ctx, `SELECT reserved_units, cooled_reserved_units FROM connections WHERE id=$1`, rid).Scan(&reserved, &cooledReserved)
	if err == nil {
		if auth.ActiveRole != models.RoleAdministrator && auth.ActiveRole != models.RoleDispatcher {
			return nil, models.Forbidden("forbidden", "forbidden")
		}
		if cap < reserved || ccap < cooledReserved {
			return nil, models.Conflict("capacity_reserved", "below reserved")
		}
		_, err = s.store.PG.Exec(ctx, `UPDATE connections SET capacity_units=$1, cooled_capacity_units=$2 WHERE id=$3`, cap, ccap, rid)
		if err != nil {
			return nil, models.Internal(err.Error())
		}
		s.bumpNetwork(ctx)
		return map[string]any{"resourceId": rid.String(), "capacityUnits": cap, "cooledCapacityUnits": ccap}, nil
	}
	return nil, models.NotFound("not_found", "resource not found")
}

func (s *Service) ConfigureLaboratoryAcceptance(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleAdministrator, models.RoleDispatcher, models.RoleLaboratoryTeam); err != nil {
		return nil, err
	}
	labID, err1 := uuid.Parse(str(body["laboratoryId"]))
	stID, err2 := uuid.Parse(str(body["sampleTypeId"]))
	if err1 != nil || err2 != nil {
		return nil, models.BadRequest("invalid_acceptance", "invalid ids")
	}
	accepts, ok := body["accepts"].(bool)
	if !ok {
		return nil, models.BadRequest("invalid_acceptance", "accepts required")
	}
	loc, err := s.getLocation(ctx, labID)
	if err != nil {
		return nil, err
	}
	if !loc.Functions.Laboratory {
		return nil, models.BadRequest("invalid_acceptance", "not a laboratory")
	}
	if auth.ActiveRole == models.RoleLaboratoryTeam {
		if auth.User.AssignedLocationID == nil || *auth.User.AssignedLocationID != labID {
			return nil, models.Forbidden("forbidden", "not assigned")
		}
	}
	if _, err := s.getSampleType(ctx, stID); err != nil {
		return nil, err
	}
	var id uuid.UUID
	err = s.store.PG.QueryRow(ctx, `
		INSERT INTO laboratory_acceptance(laboratory_id, sample_type_id, accepts)
		VALUES($1,$2,$3)
		ON CONFLICT (laboratory_id, sample_type_id) DO UPDATE SET accepts=EXCLUDED.accepts
		RETURNING id`, labID, stID, accepts).Scan(&id)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	s.bumpNetwork(ctx)
	return map[string]any{"acceptanceId": id.String(), "accepts": accepts}, nil
}

func parseCoord(v any) (models.Coordinate, error) {
	m, ok := v.(map[string]any)
	if !ok {
		return models.Coordinate{}, models.BadRequest("invalid_coordinate", "invalid coordinate")
	}
	lat, ok1 := toFloat(m["latitude"])
	lng, ok2 := toFloat(m["longitude"])
	if !ok1 || !ok2 || lat < -90 || lat > 90 || lng < -180 || lng > 180 {
		return models.Coordinate{}, models.BadRequest("invalid_coordinate", "out of range")
	}
	return models.Coordinate{Latitude: lat, Longitude: lng}, nil
}

func toFloat(v any) (float64, bool) {
	switch t := v.(type) {
	case float64:
		return t, true
	case float32:
		return float64(t), true
	case int:
		return float64(t), true
	case int64:
		return float64(t), true
	case json.Number:
		f, err := t.Float64()
		return f, err == nil
	default:
		return 0, false
	}
}

func toUUIDSlice(v any) []uuid.UUID {
	out := []uuid.UUID{}
	if v == nil {
		return out
	}
	arr, ok := v.([]any)
	if !ok {
		return out
	}
	for _, x := range arr {
		if s, ok := x.(string); ok {
			if id, err := uuid.Parse(s); err == nil {
				out = append(out, id)
			}
		}
	}
	return out
}

func (s *Service) listConnections(ctx context.Context) ([]models.Connection, error) {
	rows, err := s.store.PG.Query(ctx, `
		SELECT id,from_location_id,to_location_id,travel_minutes,cost_units,cooled,active,
		capacity_units,reserved_units,cooled_capacity_units,cooled_reserved_units FROM connections`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []models.Connection
	for rows.Next() {
		var c models.Connection
		if err := rows.Scan(&c.ID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active,
			&c.CapacityUnits, &c.ReservedUnits, &c.CooledCapacityUnits, &c.CooledReservedUnits); err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	return out, nil
}

func (s *Service) ensureServiceabilitySnapshot(ctx context.Context) error {
	var n int
	_ = s.store.PG.QueryRow(ctx, `SELECT COUNT(*) FROM serviceability_snapshots`).Scan(&n)
	if n == 0 {
		return s.recomputeServiceability(ctx)
	}
	return nil
}

func (s *Service) recomputeServiceability(ctx context.Context) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	locs, err := s.listLocations(ctx)
	if err != nil {
		return err
	}
	var regions []map[string]any
	count := 0
	for _, l := range locs {
		if l.Active && l.Functions.CollectionPoint {
			count++
			regions = append(regions, map[string]any{
				"locationId": l.ID.String(),
				"name":       l.Name,
				"latitude":   l.Coordinate.Latitude,
				"longitude":  l.Coordinate.Longitude,
				"coverageKm": l.CoverageKm,
			})
		}
	}
	if regions == nil {
		regions = []map[string]any{}
	}
	var rev, ver int
	_ = s.store.PG.QueryRow(ctx, `SELECT revision, serviceability_version FROM network_meta WHERE id=1`).Scan(&rev, &ver)
	newVer := ver + 1
	regJSON, _ := json.Marshal(regions)
	_, err = s.store.PG.Exec(ctx, `
		INSERT INTO serviceability_snapshots(version,status,computed_at,network_revision,regions,active_collection_point_count)
		VALUES($1,'complete',now(),$2,$3::jsonb,$4)`, newVer, rev, regJSON, count)
	if err != nil {
		return err
	}
	_, _ = s.store.PG.Exec(ctx, `UPDATE network_meta SET serviceability_version=$1 WHERE id=1`, newVer)
	return nil
}

func (s *Service) ReadServiceabilitySnapshot(ctx context.Context, auth *AuthContext) (map[string]any, error) {
	if auth == nil {
		return nil, models.Unauthorized("unauthorized", "unauthorized")
	}
	var ver, rev, count int
	var status string
	var computed time.Time
	var regionsJSON []byte
	err := s.store.PG.QueryRow(ctx, `
		SELECT version,status,computed_at,network_revision,regions,active_collection_point_count
		FROM serviceability_snapshots ORDER BY version DESC LIMIT 1`).Scan(&ver, &status, &computed, &rev, &regionsJSON, &count)
	if err == pgx.ErrNoRows {
		_ = s.recomputeServiceability(ctx)
		return s.ReadServiceabilitySnapshot(ctx, auth)
	}
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	var regions []map[string]any
	_ = json.Unmarshal(regionsJSON, &regions)
	if regions == nil {
		regions = []map[string]any{}
	}
	return map[string]any{
		"version":                     ver,
		"status":                      "complete",
		"computedAt":                  formatTime(computed),
		"networkRevision":             rev,
		"regions":                     regions,
		"activeCollectionPointCount":  count,
	}, nil
}
''')
print("network done")
"}

