	}
	fromID, err1 := uuid.Parse(str(body["fromLocationId"]))
	toID, err2 := uuid.Parse(str(body["toLocationId"]))
	if err1 != nil || err2 != nil {
		return nil, models.BadRequest("invalid_json", "invalid locations")
	}
	travel, ok := toFloat(body["travelMinutes"])
	if !ok || travel < 1 {
		return nil, models.BadRequest("invalid_json", "invalid travelMinutes")
	}
	cost, ok := toFloat(body["costUnits"])
	if !ok || cost < 0 {
		return nil, models.BadRequest("invalid_json", "invalid costUnits")
	}
	cooled, _ := body["cooled"].(bool)
	active, ok := body["active"].(bool)
	if !ok {
		return nil, models.BadRequest("invalid_json", "active required")
	}
	if _, err := s.getLocation(ctx, fromID); err != nil {
		return nil, err
	}
	if _, err := s.getLocation(ctx, toID); err != nil {
		return nil, err
	}
	var id uuid.UUID
	err := s.store.PG.QueryRow(ctx, `
		INSERT INTO connections(from_location_id,to_location_id,travel_minutes,cost_units,cooled,active)
