	for rows.Next() {
		var c models.Connection
		if err := rows.Scan(&c.ID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active,
			&c.CapacityUnits, &c.ReservedUnits, &c.CooledCapacityUnits, &c.CooledReservedUnits); err != nil {
			return nil, err
		}
		out = append(out, c)
