	}

	// Cleaner approach: create node assignments for intermediate locations and lab assignment
	for i := 0; i < len(rr.path)-1; i++ {
		if i > 0 || (i == 0 && len(rr.path) > 1) {
			// node at path[i] when it's intermediate (not last)
		}
	}
	for i, locID := range rr.path {
		if i == len(rr.path)-1 {
			// laboratory assignment
			aid := uuid.New()
			_, err = tx.Exec(ctx, `
				INSERT INTO assignments(id,journey_id,sample_id,kind,status,sequence,laboratory_id,expected_sample_type_id)
				VALUES($1,$2,$3,'laboratory','pending',$4,$5,$6)`, aid, jid, sampleID, asSeq, locID, st.ID)
			if err != nil {
				return uuid.Nil, nil, models.Internal(err.Error())
			}
			assignIDs = append(assignIDs, aid)
			asSeq++
		} else if i > 0 || (presealed && i == 0) {
