				INSERT INTO assignments(id,journey_id,sample_id,kind,status,sequence,node_id)
				VALUES($1,$2,$3,'node','pending',$4,$5)`, aid, jid, sampleID, asSeq, locID)
			if err != nil {
				return uuid.Nil, nil, models.Internal(err.Error())
			}
			assignIDs = append(assignIDs, aid)
			asSeq++
		}
	}

	return jid, assignIDs, nil
}

func (s *Service) reserveCapacityTx(ctx context.Context, tx pgx.Tx, resourceType string, resourceID, sampleID, journeyID uuid.UUID, units int, cooled bool) error {
	if resourceType == "location" {
		var cap, reserved, ccap, creserved int
		err := tx.QueryRow(ctx, `SELECT capacity_units,reserved_units,cooled_capacity_units,cooled_reserved_units FROM locations WHERE id=$1 FOR UPDATE`, resourceID).
			Scan(&cap, &reserved, &ccap, &creserved)
		if err != nil {
			return models.Internal(err.Error())
		}
		if reserved+units > cap {
			return models.Conflict("capacity_exhausted", "location capacity exhausted")
		}
		if cooled && creserved+units > ccap {
			return models.Conflict("cooled_capacity_exhausted", "cooled capacity exhausted")
		}
		if cooled {
			_, err = tx.Exec(ctx, `UPDATE locations SET reserved_units=reserved_units+$1, cooled_reserved_units=cooled_reserved_units+$1 WHERE id=$2`, units, resourceID)
		} else {
			_, err = tx.Exec(ctx, `UPDATE locations SET reserved_units=reserved_units+$1 WHERE id=$2`, units, resourceID)
		}
		if err != nil {
			return models.Internal(err.Error())
		}
	} else if resourceType == "connection" {
		var cap, reserved, ccap, creserved int
		err := tx.QueryRow(ctx, `SELECT capacity_units,reserved_units,cooled_capacity_units,cooled_reserved_units FROM connections WHERE id=$1 FOR UPDATE`, resourceID).
			Scan(&cap, &reserved, &ccap, &creserved)
		if err != nil {
			return models.Internal(err.Error())
		}
		if reserved+units > cap {
			return models.Conflict("capacity_exhausted", "connection capacity exhausted")
		}
		if cooled && creserved+units > ccap {
			return models.Conflict("cooled_capacity_exhausted", "cooled capacity exhausted")
		}
		if cooled {
			_, err = tx.Exec(ctx, `UPDATE connections SET reserved_units=reserved_units+$1, cooled_reserved_units=cooled_reserved_units+$1 WHERE id=$2`, units, resourceID)
		} else {
			_, err = tx.Exec(ctx, `UPDATE connections SET reserved_units=reserved_units+$1 WHERE id=$2`, units, resourceID)
		}
		if err != nil {
			return models.Internal(err.Error())
		}
	}
	_, err := tx.Exec(ctx, `
		INSERT INTO capacity_reservations(resource_type,resource_id,sample_id,journey_id,units,cooled,active)
		VALUES($1,$2,$3,$4,$5,$6,true)`, resourceType, resourceID, sampleID, journeyID, units, cooled)
	return err
}

// silence unused
var _ = pgtype.UUID{}
''')
print("journey part1 done")
"}

