func (s *Service) releaseCapacityForSample(ctx context.Context, sampleID uuid.UUID) {
	rows, err := s.store.PG.Query(ctx, `
		SELECT id, resource_type, resource_id, units, cooled FROM capacity_reservations WHERE sample_id=$1 AND active`, sampleID)
	if err != nil {
		return
	}
	defer rows.Close()
	for rows.Next() {
		var id uuid.UUID
		var rtype string
		var rid uuid.UUID
		var units int
		var cooled bool
		if err := rows.Scan(&id, &rtype, &rid, &units, &cooled); err != nil {
			continue
		}
		if rtype == "location" {
			if cooled {
				_, _ = s.store.PG.Exec(ctx, `UPDATE locations SET reserved_units=GREATEST(0,reserved_units-$1), cooled_reserved_units=GREATEST(0,cooled_reserved_units-$1) WHERE id=$2`, units, rid)
			} else {
				_, _ = s.store.PG.Exec(ctx, `UPDATE locations SET reserved_units=GREATEST(0,reserved_units-$1) WHERE id=$2`, units, rid)
			}
		} else if rtype == "connection" {
			if cooled {
				_, _ = s.store.PG.Exec(ctx, `UPDATE connections SET reserved_units=GREATEST(0,reserved_units-$1), cooled_reserved_units=GREATEST(0,cooled_reserved_units-$1) WHERE id=$2`, units, rid)
			} else {
				_, _ = s.store.PG.Exec(ctx, `UPDATE connections SET reserved_units=GREATEST(0,reserved_units-$1) WHERE id=$2`, units, rid)
