func (s *Service) offerPendingAssignments(ctx context.Context, sampleID uuid.UUID) {
	rows, err := s.store.PG.Query(ctx, `
		SELECT id, kind, expected_sample_type_id, node_id, laboratory_id, from_location_id, to_location_id
		FROM assignments WHERE sample_id=$1 AND status='pending' AND offered_to IS NULL ORDER BY sequence`, sampleID)
