		stID, nodeID, labID, fromID, toID *uuid.UUID
	}
	var list []struct {
		ID   uuid.UUID
		Kind string
		StID *uuid.UUID
		Node *uuid.UUID
		Lab  *uuid.UUID
	}
	for rows.Next() {
		var id uuid.UUID
		var kind string
		var stID, nodeID, labID, fromID, toID *uuid.UUID
		if err := rows.Scan(&id, &kind, &stID, &nodeID, &labID, &fromID, &toID); err != nil {
			continue
		}
		_ = fromID
		_ = toID
		list = append(list, struct {
			ID   uuid.UUID
			Kind string
			StID *uuid.UUID
			Node *uuid.UUID
			Lab  *uuid.UUID
		}{id, kind, stID, nodeID, labID})
