func (s *Service) offerAssignment(ctx context.Context, assignmentID uuid.UUID, kind string, stID, nodeID, labID *uuid.UUID) {
	worker, err := s.pickWorker(ctx, kind, stID, nodeID, labID, assignmentID)
	if err != nil || worker == nil {
		// flag exception if collection requires qualified and none available long-term
		return
	}
	exp := nowUTC().Add(OfferTimeout)
	_, _ = s.store.PG.Exec(ctx, `
		UPDATE assignments SET offered_to=$1, offer_expires_at=$2, status='offered', updated_at=now() WHERE id=$3`,
