w("internal/service/journey_create.go", r'''package service

import (
	"context"
	"time"

	"lablogistics/internal/models"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
)

// createJourneyPlan builds journey, stops, assignments and capacity reservations.
func (s *Service) createJourneyPlan(ctx context.Context, tx pgx.Tx, sampleID uuid.UUID, st *models.SampleType, rr routeResult, origin models.Coordinate, requestedAt time.Time, presealed bool) (uuid.UUID, []uuid.UUID, error) {
	routeMode := "direct"
	if len(rr.path) > 2 {
		routeMode = "multi_stop"
	}
	var jid uuid.UUID
	err := tx.QueryRow(ctx, `
		INSERT INTO journeys(plan_version,route_mode,status,estimated_delivery_at,total_cost_units,capacity_used,capacity_available,sample_ids,valid)
		VALUES(1,$1,'planned',$2,$3,1,0,ARRAY[$4]::uuid[],true) RETURNING id`,
		routeMode, rr.estimatedArrival, rr.totalCost, sampleID).Scan(&jid)
	if err != nil {
		return uuid.Nil, nil, models.Internal(err.Error())
	}

	cooled := st.RequiresCooledRoute
	for _, locID := range rr.path {
		if err := s.reserveCapacityTx(ctx, tx, "location", locID, sampleID, jid, 1, cooled); err != nil {
			return uuid.Nil, nil, err
		}
	}
	for _, cid := range rr.connections {
		if err := s.reserveCapacityTx(ctx, tx, "connection", cid, sampleID, jid, 1, cooled); err != nil {
			return uuid.Nil, nil, err
		}
	}

	// stops
	seq := 0
	est := requestedAt
	_, err = tx.Exec(ctx, `
		INSERT INTO journey_stops(id,journey_id,location_id,stop_type,sequence,estimated_at,latitude,longitude)
		VALUES($1,$2,$3,'pickup',$4,$5,$6,$7)`, uuid.New(), jid, rr.collectionNode, seq, est, origin.Latitude, origin.Longitude)
	if err != nil {
		return uuid.Nil, nil, models.Internal(err.Error())
	}
	seq++
	for i, locID := range rr.path {
		stType := "handoff"
		if i == len(rr.path)-1 {
			stType = "delivery"
		}
		est = est.Add(20 * time.Minute)
		_, err = tx.Exec(ctx, `
			INSERT INTO journey_stops(id,journey_id,location_id,stop_type,sequence,estimated_at)
			VALUES($1,$2,$3,$4,$5,$6)`, uuid.New(), jid, locID, stType, seq, est)
		if err != nil {
			return uuid.Nil, nil, models.Internal(err.Error())
		}
		seq++
	}

	var assignIDs []uuid.UUID
	asSeq := 0
	if !presealed {
		aid := uuid.New()
		_, err = tx.Exec(ctx, `
			INSERT INTO assignments(id,journey_id,sample_id,kind,status,sequence,to_location_id,expected_sample_type_id)
			VALUES($1,$2,$3,'collection','pending',$4,$5,$6)`, aid, jid, sampleID, asSeq, rr.collectionNode, st.ID)
		if err != nil {
			return uuid.Nil, nil, models.Internal(err.Error())
		}
		assignIDs = append(assignIDs, aid)
		asSeq++
	}

	// transport legs between consecutive path nodes
	for i := 0; i < len(rr.path)-1; i++ {
		from := rr.path[i]
		to := rr.path[i+1]
		aid := uuid.New()
		_, err = tx.Exec(ctx, `
			INSERT INTO assignments(id,journey_id,sample_id,kind,status,sequence,from_location_id,to_location_id)
			VALUES($1,$2,$3,'transport','pending',$4,$5,$6)`, aid, jid, sampleID, asSeq, from, to)
		if err != nil {
			return uuid.Nil, nil, models.Internal(err.Error())
		}
		assignIDs = append(assignIDs, aid)
		asSeq++
	}

	// node assignments for intermediate nodes (and entry node if presealed)
	startIdx := 1
	if presealed {
		startIdx = 0
	}
	for i := startIdx; i < len(rr.path)-1; i++ {
		aid := uuid.New()
		_, err = tx.Exec(ctx, `
			INSERT INTO assignments(id,journey_id,sample_id,kind,status,sequence,node_id)
			VALUES($1,$2,$3,'node','pending',$4,$5)`, aid, jid, sampleID, asSeq, rr.path[i])
		if err != nil {
			return uuid.Nil, nil, models.Internal(err.Error())
		}
		assignIDs = append(assignIDs, aid)
		asSeq++
	}

	// laboratory assignment
	if len(rr.path) > 0 {
		lab := rr.path[len(rr.path)-1]
		aid := uuid.New()
		_, err = tx.Exec(ctx, `
			INSERT INTO assignments(id,journey_id,sample_id,kind,status,sequence,laboratory_id,expected_sample_type_id)
			VALUES($1,$2,$3,'laboratory','pending',$4,$5,$6)`, aid, jid, sampleID, asSeq, lab, st.ID)
		if err != nil {
			return uuid.Nil, nil, models.Internal(err.Error())
		}
		assignIDs = append(assignIDs, aid)
	}

	return jid, assignIDs, nil
}
''')

