func (s *Service) buildJourneyPlan(ctx context.Context, jid uuid.UUID) (map[string]any, error) {
	var j models.Journey
	var sampleIDs, workerIDs []uuid.UUID
	err := s.store.PG.QueryRow(ctx, `
		SELECT id,parent_journey_id,plan_version,route_mode,status,estimated_delivery_at,total_cost_units,
		capacity_used,capacity_available,sample_ids,assigned_worker_ids,valid,replan_status,replacement_journey_id
		FROM journeys WHERE id=$1`, jid).Scan(
		&j.ID, &j.ParentJourneyID, &j.PlanVersion, &j.RouteMode, &j.Status, &j.EstimatedDeliveryAt,
		&j.TotalCostUnits, &j.CapacityUsed, &j.CapacityAvailable, &sampleIDs, &workerIDs, &j.Valid, &j.ReplanStatus, &j.ReplacementJourneyID)
	if err == pgx.ErrNoRows {
		return nil, models.NotFound("not_found", "journey")
	}
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	j.SampleIDs = sampleIDs
	j.AssignedWorkerIDs = workerIDs

	// stops
	srows, err := s.store.PG.Query(ctx, `
		SELECT id,location_id,stop_type,sequence,estimated_at,dwell_minutes,latitude,longitude,completed_at
		FROM journey_stops WHERE journey_id=$1 ORDER BY sequence`, jid)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	defer srows.Close()
	stops := []map[string]any{}
	for srows.Next() {
		var sid uuid.UUID
		var locID *uuid.UUID
		var stopType string
		var seq, dwell int
		var est time.Time
		var lat, lng *float64
		var completed *time.Time
		if err := srows.Scan(&sid, &locID, &stopType, &seq, &est, &dwell, &lat, &lng, &completed); err != nil {
			continue
		}
		st := map[string]any{
			"stopId": sid.String(), "stopType": stopType, "sequence": seq, "estimatedAt": formatTime(est),
		}
		if locID != nil {
			st["locationId"] = locID.String()
		} else {
			st["locationId"] = uuid.Nil.String()
		}
		if dwell > 0 {
			st["dwellMinutes"] = dwell
		}
		if lat != nil && lng != nil {
			st["coordinate"] = models.Coordinate{Latitude: *lat, Longitude: *lng}
		}
		if completed != nil {
			st["completedAt"] = formatTime(*completed)
		}
		stops = append(stops, st)
	}

	arows, err := s.store.PG.Query(ctx, `
		SELECT id,sequence,status,from_location_id,to_location_id,worker_id,sample_id,kind
		FROM assignments WHERE journey_id=$1 ORDER BY sequence`, jid)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	defer arows.Close()
	legs := []map[string]any{}
	var collectionIDs, nodeIDs, labIDs []string
	var firstTransport, middleTransport, finalTransport string
	transportCount := 0
	assignedWorkers := []string{}
	seenW := map[string]bool{}
	for arows.Next() {
		var id uuid.UUID
		var seq int
		var status string
		var fromID, toID, workerID *uuid.UUID
		var sampleID uuid.UUID
		var kind string
		if err := arows.Scan(&id, &seq, &status, &fromID, &toID, &workerID, &sampleID, &kind); err != nil {
			continue
		}
		if kind == "transport" {
			leg := map[string]any{
				"assignmentId": id.String(), "sequence": seq, "status": status, "sampleId": sampleID.String(),
			}
			if fromID != nil {
				leg["fromLocationId"] = fromID.String()
			}
			if toID != nil {
				leg["toLocationId"] = toID.String()
			}
			if workerID != nil {
				leg["workerId"] = workerID.String()
				if !seenW[workerID.String()] {
					assignedWorkers = append(assignedWorkers, workerID.String())
					seenW[workerID.String()] = true
				}
			}
			legs = append(legs, leg)
			transportCount++
			if transportCount == 1 {
				firstTransport = id.String()
			} else {
				middleTransport = id.String()
			}
			finalTransport = id.String()
		}
		if kind == "collection" {
			collectionIDs = append(collectionIDs, id.String())
		}
		if kind == "node" {
			nodeIDs = append(nodeIDs, id.String())
		}
		if kind == "laboratory" {
			labIDs = append(labIDs, id.String())
		}
		if workerID != nil && !seenW[workerID.String()] {
			assignedWorkers = append(assignedWorkers, workerID.String())
			seenW[workerID.String()] = true
		}
	}
	sids := make([]string, 0, len(j.SampleIDs))
	for _, id := range j.SampleIDs {
		sids = append(sids, id.String())
	}
	out := map[string]any{
		"journeyId":    j.ID.String(),
		"planVersion":  j.PlanVersion,
		"routeMode":    j.RouteMode,
		"status":       j.Status,
		"sampleIds":    sids,
		"orderedStops": stops,
		"legs":         legs,
		"valid":        j.Valid,
	}
	if j.ParentJourneyID != nil {
		out["parentJourneyId"] = j.ParentJourneyID.String()
	}
	if j.EstimatedDeliveryAt != nil {
		out["estimatedDeliveryAt"] = formatTime(*j.EstimatedDeliveryAt)
	}
	out["totalCostUnits"] = j.TotalCostUnits
	out["capacityUsed"] = j.CapacityUsed
	out["capacityAvailable"] = j.CapacityAvailable
	out["assignedWorkerIds"] = assignedWorkers
	if len(collectionIDs) > 0 {
		out["collectionAssignmentId"] = collectionIDs[0]
		out["collectionAssignmentIds"] = collectionIDs
	}
	if len(nodeIDs) > 0 {
		out["nodeAssignmentIds"] = nodeIDs
	}
	if len(labIDs) > 0 {
		out["laboratoryAssignmentIds"] = labIDs
	}
	if firstTransport != "" {
		out["firstTransportAssignmentId"] = firstTransport
	}
	if middleTransport != "" && middleTransport != firstTransport && middleTransport != finalTransport {
		out["middleTransportAssignmentId"] = middleTransport
	}
	if finalTransport != "" {
		out["finalTransportAssignmentId"] = finalTransport
	}
	if j.ReplanStatus != nil {
		out["replanStatus"] = *j.ReplanStatus
	}
	return out, nil
}

func (s *Service) ReadJourneyPlan(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if auth == nil {
		return nil, models.Unauthorized("unauthorized", "unauthorized")
	}
	jid, err := uuid.Parse(str(body["journeyId"]))
	if err != nil {
		return nil, models.NotFound("not_found", "journey")
	}
	plan, err := s.buildJourneyPlan(ctx, jid)
	if err != nil {
		return nil, err
	}
	// role-scoped views
	switch auth.ActiveRole {
	case models.RoleRequester:
		// limited view
		limited := map[string]any{
			"journeyId": plan["journeyId"],
			"sampleIds": plan["sampleIds"],
			"legs":      plan["legs"],
		}
		if v, ok := plan["parentJourneyId"]; ok {
			limited["parentJourneyId"] = v
		}
		if v, ok := plan["planVersion"]; ok {
			limited["planVersion"] = v
		}
		if v, ok := plan["routeMode"]; ok {
			limited["routeMode"] = v
		}
		if v, ok := plan["status"]; ok {
			limited["status"] = v
		}
		if v, ok := plan["estimatedDeliveryAt"]; ok {
			limited["estimatedDeliveryAt"] = v
		}
		if v, ok := plan["totalCostUnits"]; ok {
			limited["totalCostUnits"] = v
		}
		if v, ok := plan["orderedStops"]; ok {
			limited["orderedStops"] = v
		}
		return limited, nil
	case models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam:
		// worker view - only assigned legs
		arows, _ := s.store.PG.Query(ctx, `SELECT id FROM assignments WHERE journey_id=$1 AND worker_id=$2`, jid, auth.User.ID)
		aids := []string{}
		if arows != nil {
			defer arows.Close()
			for arows.Next() {
				var id uuid.UUID
				if arows.Scan(&id) == nil {
					aids = append(aids, id.String())
				}
			}
		}
		legs, _ := plan["legs"].([]map[string]any)
		filtered := []map[string]any{}
		for _, leg := range legs {
			if wid, ok := leg["workerId"].(string); ok && wid == auth.User.ID.String() {
				filtered = append(filtered, leg)
			}
			// also include if assignment id in aids - already handled
			_ = aids
		}
		// rebuild with scope
		out := map[string]any{
			"journeyId":     plan["journeyId"],
			"planVersion":   plan["planVersion"],
			"routeMode":     plan["routeMode"],
			"status":        plan["status"],
			"scope":         "assigned_legs",
			"assignmentIds": aids,
			"legs":          filtered,
			"orderedStops":  plan["orderedStops"],
		}
		if v, ok := plan["sampleIds"]; ok {
			out["sampleIds"] = v
		}
		if v, ok := plan["estimatedDeliveryAt"]; ok {
			out["estimatedDeliveryAt"] = v
		}
		if v, ok := plan["collectionAssignmentIds"]; ok {
			out["collectionAssignmentIds"] = v
		}
		if v, ok := plan["nodeAssignmentIds"]; ok {
			out["nodeAssignmentIds"] = v
		}
		if v, ok := plan["laboratoryAssignmentIds"]; ok {
			out["laboratoryAssignmentIds"] = v
		}
		if v, ok := plan["assignedWorkerIds"]; ok {
			out["assignedWorkerIds"] = v
		}
		return out, nil
	default:
		return plan, nil
	}
}

func (s *Service) ListRoleWork(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if auth == nil {
		return nil, models.Unauthorized("unauthorized", "unauthorized")
	}
	role := str(body["role"])
	if role == "" {
		role = auth.ActiveRole
	}
	if role == "" {
		return nil, models.Conflict("role_not_selected", "role not selected")
	}
	if !auth.RoleSelected && auth.ActiveRole == "" {
		return nil, models.Conflict("role_not_selected", "role not selected")
	}
	pending := []map[string]any{}
	inProgress := []map[string]any{}
	completed := []map[string]any{}

	switch role {
	case models.RoleRequester:
		rows, err := s.store.PG.Query(ctx, `SELECT id, request_id, status, serviceability, requested_at, delivery_deadline,
			earliest_collection_at, latest_collection_at, active_journey_id, target_laboratory_id, current_holder_id, requester_id,
			location_recorded_at FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, auth.User.ID)
		if err != nil {
			return nil, models.Internal(err.Error())
		}
		defer rows.Close()
		for rows.Next() {
			item := s.scanSampleWorkItem(ctx, rows)
			if item == nil {
				continue
			}
			st := str(item["status"])
			switch {
			case st == "received" || st == "cancelled" || st == "exception":
				completed = append(completed, item)
			case st == "requested" || st == "awaiting_collection":
				pending = append(pending, item)
			default:
				inProgress = append(inProgress, item)
			}
		}
	case models.RoleAdministrator, models.RoleDispatcher:
		rows, err := s.store.PG.Query(ctx, `SELECT id, request_id, status, serviceability, requested_at, delivery_deadline,
			earliest_collection_at, latest_collection_at, active_journey_id, target_laboratory_id, current_holder_id, requester_id,
			location_recorded_at FROM samples ORDER BY created_at DESC LIMIT 500`)
		if err != nil {
			return nil, models.Internal(err.Error())
		}
		defer rows.Close()
		for rows.Next() {
			item := s.scanSampleWorkItem(ctx, rows)
			if item == nil {
				continue
			}
			st := str(item["status"])
			switch {
			case st == "received" || st == "cancelled" || st == "exception":
				completed = append(completed, item)
			case st == "requested" || st == "awaiting_collection":
				pending = append(pending, item)
			default:
				inProgress = append(inProgress, item)
			}
		}
		// also journeys
		jrows, _ := s.store.PG.Query(ctx, `SELECT id, status, route_mode, plan_version, sample_ids, estimated_delivery_at FROM journeys ORDER BY created_at DESC LIMIT 200`)
		if jrows != nil {
			defer jrows.Close()
			for jrows.Next() {
				var id uuid.UUID
				var status, mode string
				var pv int
				var sids []uuid.UUID
				var eta *time.Time
				if jrows.Scan(&id, &status, &mode, &pv, &sids, &eta) != nil {
					continue
				}
				ss := make([]string, 0, len(sids))
				for _, x := range sids {
					ss = append(ss, x.String())
				}
				var acount int
				_ = s.store.PG.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE journey_id=$1`, id).Scan(&acount)
				hist, _ := s.entityTimeline(ctx, "journey", id.String())
				item := map[string]any{
					"kind": "journey", "journeyId": id.String(), "status": status, "routeMode": mode,
					"planVersion": pv, "sampleIds": ss, "assignmentCount": acount, "history": hist,
				}
				if eta != nil {
					item["estimatedDeliveryAt"] = formatTime(*eta)
				} else {
					item["estimatedDeliveryAt"] = formatTime(nowUTC())
				}
				switch status {
				case "completed", "cancelled":
					completed = append(completed, item)
				case "planned":
					pending = append(pending, item)
				default:
					inProgress = append(inProgress, item)
				}
			}
		}
	default:
		// worker assignments
		rows, err := s.store.PG.Query(ctx, `
			SELECT id, kind, sample_id, status, journey_id, from_location_id, to_location_id, sequence,
			offer_expires_at, node_id, laboratory_id, expected_sample_type_id, completed
			FROM assignments
			WHERE (worker_id=$1 OR offered_to=$1)
			ORDER BY created_at DESC LIMIT 300`, auth.User.ID)
		if err != nil {
			return nil, models.Internal(err.Error())
		}
		defer rows.Close()
		for rows.Next() {
			var id, sampleID, journeyID uuid.UUID
			var kind, status string
			var fromID, toID, nodeID, labID, stID *uuid.UUID
			var seq int
			var offerExp *time.Time
			var completed bool
			if err := rows.Scan(&id, &kind, &sampleID, &status, &journeyID, &fromID, &toID, &seq, &offerExp, &nodeID, &labID, &stID, &completed); err != nil {
				continue
			}
			hist, _ := s.entityTimeline(ctx, "assignment", id.String())
			item := map[string]any{
				"kind": kind, "assignmentId": id.String(), "sampleId": sampleID.String(),
				"status": status, "history": hist,
			}
			item["journeyId"] = journeyID.String()
			if fromID != nil {
				item["fromLocationId"] = fromID.String()
			}
			if toID != nil {
				item["toLocationId"] = toID.String()
			}
			item["sequence"] = seq
			if offerExp != nil {
				item["offerExpiresAt"] = formatTime(*offerExp)
			}
			if nodeID != nil {
				item["nodeId"] = nodeID.String()
			}
			if labID != nil {
				item["laboratoryId"] = labID.String()
			}
			if stID != nil {
				item["expectedSampleTypeId"] = stID.String()
			}
			// capacity for lab/node
			if (kind == "laboratory" || kind == "node") && (labID != nil || nodeID != nil) {
				lid := labID
				if lid == nil {
					lid = nodeID
				}
				if loc, err := s.getLocation(ctx, *lid); err == nil {
					item["destinationCapacity"] = loc.Capacity()
				}
			}
			switch {
			case completed || status == "completed" || status == "cancelled":
				completed = append(completed, item)
			case status == "offered" || status == "pending":
				pending = append(pending, item)
			default:
				inProgress = append(inProgress, item)
			}
		}
	}
	return map[string]any{"pending": pending, "inProgress": inProgress, "completed": completed}, nil
}

func (s *Service) scanSampleWorkItem(ctx context.Context, row pgx.Row) map[string]any {
	var id, reqID, requesterID uuid.UUID
	var status, serv string
	var requestedAt, deadline, earliest, latest time.Time
	var journeyID, labID, holderID *uuid.UUID
	var locAt *time.Time
	if err := row.Scan(&id, &reqID, &status, &serv, &requestedAt, &deadline, &earliest, &latest, &journeyID, &labID, &holderID, &requesterID, &locAt); err != nil {
		return nil
	}
	hist, _ := s.GetTimeline(ctx, id)
	item := map[string]any{
		"kind": "sample", "sampleId": id.String(), "requestId": reqID.String(), "status": status,
		"history": hist, "locationStale": models.IsLocationStale(locAt, nowUTC()),
		"serviceability": serv, "requestedAt": formatTime(requestedAt), "deliveryDeadline": formatTime(deadline),
		"earliestCollectionAt": formatTime(earliest), "latestCollectionAt": formatTime(latest),
		"requesterId": requesterID.String(),
	}
	if journeyID != nil {
		item["journeyId"] = journeyID.String()
		item["activeJourneyId"] = journeyID.String()
	}
	if labID != nil {
		item["laboratoryId"] = labID.String()
	}
	if holderID != nil {
		item["currentHolderId"] = holderID.String()
	}
	if locAt != nil {
		item["locationRecordedAt"] = formatTime(*locAt)
	}
	return item
}

func (s *Service) entityTimeline(ctx context.Context, entityType, entityID string) ([]models.TimelineEntry, error) {
	cur, err := s.store.MG.Collection("timeline_events").Find(ctx,
		bson.M{"entity_type": entityType, "entity_id": entityID},
		options.Find().SetSort(bson.D{{Key: "occurred_at", Value: 1}}).SetLimit(100),
	)
	if err != nil {
		return []models.TimelineEntry{}, nil
	}
	defer cur.Close(ctx)
	out := []models.TimelineEntry{}
	for cur.Next(ctx) {
		var doc bson.M
		if cur.Decode(&doc) != nil {
			continue
		}
		entry := models.TimelineEntry{
			EventID: toInt64(doc["event_id"]), Action: str(doc["action"]), ActorID: str(doc["actor_id"]),
			Role: str(doc["role"]), EntityType: str(doc["entity_type"]), EntityID: str(doc["entity_id"]),
			Success: toBool(doc["success"]), Details: toMap(doc["details"]),
		}
		if t, ok := doc["occurred_at"].(time.Time); ok {
			entry.OccurredAt = t
		}
		out = append(out, entry)
	}
	return out, nil
}

func (s *Service) ReadOperationsState(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireAdminOrDispatcher(auth); err != nil {
		// also lab workers can see limited? contract says dispatcher monitor
		if auth == nil {
			return nil, models.Unauthorized("unauthorized", "unauthorized")
		}
		if auth.ActiveRole != models.RoleLaboratoryTeam && auth.ActiveRole != models.RoleNodeHandler {
			return nil, err
		}
	}
	return s.buildOperationsState(ctx)
}

func (s *Service) buildOperationsState(ctx context.Context) (map[string]any, error) {
	now := nowUTC()
	samples := []map[string]any{}
	srows, _ := s.store.PG.Query(ctx, `
		SELECT id,status,request_id,origin_lat,origin_lng,delivery_deadline,current_holder_id,active_journey_id,
		latest_lat,latest_lng,location_recorded_at FROM samples ORDER BY created_at DESC LIMIT 500`)
	if srows != nil {
		defer srows.Close()
		for srows.Next() {
			var id, reqID uuid.UUID
			var status string
			var olat, olng float64
			var deadline time.Time
			var holder, journey *uuid.UUID
			var llat, llng *float64
			var locAt *time.Time
			if srows.Scan(&id, &status, &reqID, &olat, &olng, &deadline, &holder, &journey, &llat, &llng, &locAt) != nil {
				continue
			}
			item := map[string]any{
				"sampleId": id.String(), "status": status, "locationStale": models.IsLocationStale(locAt, now),
				"requestId": reqID.String(), "origin": models.Coordinate{Latitude: olat, Longitude: olng},
				"deliveryDeadline": formatTime(deadline),
			}
			if holder != nil {
				item["currentHolderId"] = holder.String()
			}
			if journey != nil {
				item["activeJourneyId"] = journey.String()
			}
			if llat != nil {
				item["latestLocation"] = models.Coordinate{Latitude: *llat, Longitude: *llng}
			}
			if locAt != nil {
				item["locationRecordedAt"] = formatTime(*locAt)
			}
			samples = append(samples, item)
		}
	}

	workers := []map[string]any{}
	wrows, _ := s.store.PG.Query(ctx, `
		SELECT id, full_name, roles, available, capacity_units, assignment_count, latest_lat, latest_lng, location_recorded_at
		FROM users WHERE roles && ARRAY['collection_professional','delivery_partner','node_handler','laboratory_team']::text[]`)
	if wrows != nil {
		defer wrows.Close()
		for wrows.Next() {
			var id uuid.UUID
			var name string
			var roles []string
			var available bool
			var cap, acount int
			var lat, lng *float64
			var locAt *time.Time
			if wrows.Scan(&id, &name, &roles, &available, &cap, &acount, &lat, &lng, &locAt) != nil {
				continue
			}
			st := "unavailable"
			if available {
				st = "available"
			}
			item := map[string]any{
				"workerId": id.String(), "available": available, "status": st,
				"capacityUnits": cap, "assignmentCount": acount, "locationStale": models.IsLocationStale(locAt, now),
				"fullName": name, "roles": roles,
			}
			if lat != nil {
				item["latestLocation"] = models.Coordinate{Latitude: *lat, Longitude: *lng}
			}
			if locAt != nil {
				item["locationRecordedAt"] = formatTime(*locAt)
			}
			workers = append(workers, item)
		}
	}

	locations := []map[string]any{}
	locs, _ := s.listLocations(ctx)
	for _, l := range locs {
		accepted := []string{}
		if l.Functions.Laboratory {
			r2, _ := s.store.PG.Query(ctx, `SELECT sample_type_id FROM laboratory_acceptance WHERE laboratory_id=$1 AND accepts=true`, l.ID)
			if r2 != nil {
				for r2.Next() {
					var sid uuid.UUID
					if r2.Scan(&sid) == nil {
						accepted = append(accepted, sid.String())
					}
				}
				r2.Close()
			}
		}
		item := map[string]any{
			"id": l.ID.String(), "locationId": l.ID.String(), "name": l.Name,
			"coordinate": l.Coordinate, "active": l.Active, "coverageKm": l.CoverageKm,
			"handlingMinutes": l.HandlingMinutes, "functions": l.Functions,
			"capacity": l.Capacity(), "acceptedSampleTypeIds": accepted,
		}
		locations = append(locations, item)
	}

	connections := []map[string]any{}
	conns, _ := s.listConnections(ctx)
	for _, c := range conns {
		connections = append(connections, map[string]any{
			"id": c.ID.String(), "connectionId": c.ID.String(),
			"fromLocationId": c.FromLocationID.String(), "toLocationId": c.ToLocationID.String(),
			"travelMinutes": c.TravelMinutes, "costUnits": c.CostUnits, "cooled": c.Cooled, "active": c.Active,
			"capacity": c.Capacity(),
		})
	}

	// routes from journeys
	routes := []map[string]any{}
	jrows, _ := s.store.PG.Query(ctx, `SELECT id, status, route_mode, sample_ids FROM journeys WHERE status NOT IN ('cancelled') LIMIT 200`)
	if jrows != nil {
		defer jrows.Close()
		for jrows.Next() {
			var id uuid.UUID
			var status, mode string
			var sids []uuid.UUID
			if jrows.Scan(&id, &status, &mode, &sids) != nil {
				continue
			}
			ss := make([]string, len(sids))
			for i, x := range sids {
				ss[i] = x.String()
			}
			routes = append(routes, map[string]any{"journeyId": id.String(), "status": status, "routeMode": mode, "sampleIds": ss})
		}
	}

	handoffs := []map[string]any{}
	hrows, _ := s.store.PG.Query(ctx, `SELECT id, sample_id, status, sender_id, receiver_id FROM handoffs ORDER BY created_at DESC LIMIT 100`)
	if hrows != nil {
		defer hrows.Close()
		for hrows.Next() {
			var id, sid, sender, receiver uuid.UUID
			var status string
			if hrows.Scan(&id, &sid, &status, &sender, &receiver) != nil {
				continue
			}
			handoffs = append(handoffs, map[string]any{
				"handoffId": id.String(), "sampleId": sid.String(), "status": status,
				"senderId": sender.String(), "receiverId": receiver.String(),
			})
		}
	}

	exceptions := []map[string]any{}
	erows, _ := s.store.PG.Query(ctx, `SELECT id, status, exception FROM samples WHERE status='exception' OR exception IS NOT NULL LIMIT 100`)
	if erows != nil {
		defer erows.Close()
		for erows.Next() {
			var id uuid.UUID
			var status string
			var exc []byte
			if erows.Scan(&id, &status, &exc) != nil {
				continue
			}
			var emap map[string]any
			_ = json.Unmarshal(exc, &emap)
			exceptions = append(exceptions, map[string]any{"sampleId": id.String(), "status": status, "exception": emap})
		}
	}

	// assignment spread
	var minC, maxC int
	_ = s.store.PG.QueryRow(ctx, `
		SELECT COALESCE(MIN(assignment_count),0), COALESCE(MAX(assignment_count),0) FROM users
		WHERE roles && ARRAY['collection_professional','delivery_partner']::text[] AND active`).Scan(&minC, &maxC)
	spread := maxC - minC
	var ineligible int
	_ = s.store.PG.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE status='pending' AND offered_to IS NULL AND created_at < now() - interval '5 minutes'`).Scan(&ineligible)

	return map[string]any{
		"samples": samples, "workers": workers, "locations": locations, "connections": connections,
		"routes": routes, "handoffs": handoffs, "delays": []map[string]any{}, "exceptions": exceptions,
		"assignmentCountSpread": spread, "ineligibleAssignmentCount": ineligible,
	}, nil
}

func (s *Service) UIBootstrap(ctx context.Context, auth *AuthContext) (map[string]any, error) {
	if auth == nil {
		return nil, models.Unauthorized("unauthorized", "unauthorized")
	}
	user := map[string]any{
		"userId":                 auth.User.ID.String(),
		"username":               auth.User.Username,
		"roles":                  auth.User.Roles,
		"activeRole":             auth.ActiveRole,
		"roleSelectionRequired":  !auth.RoleSelected || auth.ActiveRole == "",
	}
	if auth.User.FullName != "" {
		user["fullName"] = auth.User.FullName
	}
	out := map[string]any{
		"user":       user,
		"serverTime": formatTime(nowUTC()),
	}
	if auth.ActiveRole == models.RoleRequester || contains(auth.User.Roles, models.RoleRequester) {
		// requester samples
		samples := []map[string]any{}
		rows, _ := s.store.PG.Query(ctx, `SELECT id, status, serviceability, delivery_deadline FROM samples WHERE requester_id=$1 ORDER BY created_at DESC LIMIT 50`, auth.User.ID)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var id uuid.UUID
				var st, serv string
				var dl time.Time
