w("internal/api/handler.go", r'''package api

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"

	"lablogistics/internal/models"
	"lablogistics/internal/service"

	"github.com/google/uuid"
	"github.com/gorilla/mux"
	"github.com/gorilla/websocket"
)

type Handler struct {
	svc       *service.Service
	staticDir string
	mapAssets string
	upgrader  websocket.Upgrader
}

func NewHandler(svc *service.Service, staticDir, mapAssets string) *Handler {
	return &Handler{
		svc: svc, staticDir: staticDir, mapAssets: mapAssets,
		upgrader: websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }},
	}
}

func (h *Handler) Router() http.Handler {
	r := mux.NewRouter()
	r.HandleFunc("/ready", h.ready).Methods("GET")

	api := r.PathPrefix("/api").Subrouter()
	api.HandleFunc("/authenticate-user", h.authenticate).Methods("POST")
	api.HandleFunc("/select-active-role", h.auth(h.selectRole)).Methods("POST")
	api.HandleFunc("/create-user", h.auth(h.createUser)).Methods("POST")
	api.HandleFunc("/update-user-access", h.auth(h.updateUserAccess)).Methods("POST")
	api.HandleFunc("/read-user/{userId}", h.auth(h.readUser)).Methods("GET")
	api.HandleFunc("/set-worker-availability", h.auth(h.setWorkerAvailability)).Methods("POST")

	api.HandleFunc("/create-sample-type", h.auth(h.createSampleType)).Methods("POST")
	api.HandleFunc("/update-sample-type", h.auth(h.updateSampleType)).Methods("POST")
	api.HandleFunc("/create-location", h.auth(h.createLocation)).Methods("POST")
	api.HandleFunc("/update-location", h.auth(h.updateLocation)).Methods("POST")
	api.HandleFunc("/set-location-status", h.auth(h.setLocationStatus)).Methods("POST")
	api.HandleFunc("/set-location-function-status", h.auth(h.setLocationFunctionStatus)).Methods("POST")
	api.HandleFunc("/create-connection", h.auth(h.createConnection)).Methods("POST")
	api.HandleFunc("/set-connection-status", h.auth(h.setConnectionStatus)).Methods("POST")
	api.HandleFunc("/configure-capacity", h.auth(h.configureCapacity)).Methods("POST")
