	api.HandleFunc("/check-serviceability", h.auth(h.checkServiceability)).Methods("POST")
	api.HandleFunc("/read-serviceability-snapshot", h.auth(h.readServiceabilitySnapshot)).Methods("POST")
	api.HandleFunc("/create-collection-request", h.auth(h.createCollectionRequest)).Methods("POST")
	api.HandleFunc("/ingest-presealed-sample", h.auth(h.ingestPresealed)).Methods("POST")

	api.HandleFunc("/accept-assignment", h.auth(h.acceptAssignment)).Methods("POST")
	api.HandleFunc("/decline-assignment", h.auth(h.declineAssignment)).Methods("POST")
	api.HandleFunc("/collect-and-seal-sample", h.auth(h.collectAndSeal)).Methods("POST")
