	api.HandleFunc("/confirm-handoff", h.auth(h.confirmHandoff)).Methods("POST")
	api.HandleFunc("/confirm-laboratory-receipt", h.auth(h.confirmLabReceipt)).Methods("POST")
	api.HandleFunc("/record-laboratory-exception", h.auth(h.recordLabException)).Methods("POST")
	api.HandleFunc("/record-handling-checkpoint", h.auth(h.recordCheckpoint)).Methods("POST")
	api.HandleFunc("/record-worker-location", h.auth(h.recordWorkerLocation)).Methods("POST")
