	api.HandleFunc("/read-sample-lifecycle", h.auth(h.readSampleLifecycle)).Methods("POST")
	api.HandleFunc("/read-journey-plan", h.auth(h.readJourneyPlan)).Methods("POST")
	api.HandleFunc("/list-role-work", h.auth(h.listRoleWork)).Methods("POST")
