func (h *Handler) events(w http.ResponseWriter, r *http.Request) {
	// WebSocket with subprotocol auth
	token := ""
	for _, p := range websocket.Subprotocols(r) {
		if strings.HasPrefix(p, "bearer.") {
			raw := strings.TrimPrefix(p, "bearer.")
			if b, err := base64.RawURLEncoding.DecodeString(raw); err == nil {
				token = string(b)
			} else if b, err := base64.URLEncoding.DecodeString(raw); err == nil {
				token = string(b)
			} else {
				token = raw
			}
		}
	}
	if token == "" {
		token = bearerToken(r)
	}
	auth, err := h.svc.ResolveSession(r.Context(), token)
	if err != nil {
		writeAppErr(w, err)
		return
	}
	up := h.upgrader
	up.Subprotocols = []string{"lab-logistics-v1"}
	conn, err := up.Upgrade(w, r, http.Header{"Sec-WebSocket-Protocol": []string{"lab-logistics-v1"}})
	if err != nil {
		return
	}
	defer conn.Close()
	ch := h.svc.Hub().Subscribe(auth.User.ID.String(), auth.ActiveRole)
	defer h.svc.Hub().Unsubscribe(ch)

	// replay since
	since := r.URL.Query().Get("since")
	if since != "" {
		// replay from mongo
		// simplified: skip detailed replay implementation for now by sending a hello
	}
	_ = conn.WriteJSON(map[string]any{"type": "connected", "role": auth.ActiveRole})

	done := make(chan struct{})
	go func() {
		defer close(done)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				return
			}
		}
	}()
	for {
		select {
		case <-done:
			return
		case ev, ok := <-ch:
			if !ok {
				return
			}
			if err := conn.WriteJSON(ev); err != nil {
				return
			}
		}
	}
}
