func cors(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
		if r.Method == http.MethodOptions {
			w.WriteHeader(204)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func (h *Handler) ready(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 3*time.Second)
	defer cancel()
	if err := h.svc.Store().Ping(ctx); err != nil {
		writeErr(w, 503, "not_ready", err.Error())
		return
	}
	writeJSON(w, 200, map[string]any{"status": "ready"})
}

func (h *Handler) spa(w http.ResponseWriter, r *http.Request) {
	path := filepath.Join(h.staticDir, filepath.Clean(r.URL.Path))
	if !strings.HasPrefix(path, h.staticDir) {
		http.NotFound(w, r)
		return
	}
	if info, err := os.Stat(path); err == nil && !info.IsDir() {
		http.ServeFile(w, r, path)
		return
	}
	index := filepath.Join(h.staticDir, "index.html")
	if _, err := os.Stat(index); err == nil {
		http.ServeFile(w, r, index)
		return
	}
	w.Header().Set("Content-Type", "text/html")
	_, _ = w.Write([]byte(`<!doctype html><html><body><p>Frontend not built</p></body></html>`))
}

type ctxKey int

const authKey ctxKey = 1

func (h *Handler) auth(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		token := bearerToken(r)
		auth, err := h.svc.ResolveSession(r.Context(), token)
		if err != nil {
			writeAppErr(w, err)
			return
		}
		ctx := context.WithValue(r.Context(), authKey, auth)
		next(w, r.WithContext(ctx))
	}
}

func getAuth(r *http.Request) *service.AuthContext {
	v, _ := r.Context().Value(authKey).(*service.AuthContext)
	return v
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(strings.ToLower(h), "bearer ") {
		return strings.TrimSpace(h[7:])
	}
	return ""
}

func decodeBody(r *http.Request) (map[string]any, error) {
	defer r.Body.Close()
	b, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil {
		return nil, models.BadRequest("invalid_json", "invalid json")
	}
	if len(b) == 0 {
		return map[string]any{}, nil
	}
	var m map[string]any
	dec := json.NewDecoder(strings.NewReader(string(b)))
	dec.UseNumber()
	if err := dec.Decode(&m); err != nil {
		return nil, models.BadRequest("invalid_json", "invalid json")
	}
	// convert json.Number to float64
	normalizeNumbers(m)
	return m, nil
}

func normalizeNumbers(m map[string]any) {
	for k, v := range m {
		switch t := v.(type) {
		case json.Number:
			if i, err := t.Int64(); err == nil {
				m[k] = float64(i)
			} else if f, err := t.Float64(); err == nil {
				m[k] = f
			} else {
				m[k] = t.String()
			}
		case map[string]any:
			normalizeNumbers(t)
		case []any:
			for i, x := range t {
				if n, ok := x.(json.Number); ok {
					if iv, err := n.Int64(); err == nil {
						t[i] = float64(iv)
					} else if f, err := n.Float64(); err == nil {
						t[i] = f
					}
				} else if mm, ok := x.(map[string]any); ok {
					normalizeNumbers(mm)
				}
			}
		}
	}
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeData(w http.ResponseWriter, status int, data any) {
	writeJSON(w, status, map[string]any{"data": data})
}

func writeErr(w http.ResponseWriter, status int, code, msg string) {
	writeJSON(w, status, map[string]any{"error": msg, "code": code})
}

func writeAppErr(w http.ResponseWriter, err error) {
	var ae *models.AppError
	if errors.As(err, &ae) {
		writeErr(w, ae.HTTPStatus, ae.Code, ae.Message)
		return
	}
	writeErr(w, 500, "internal_error", err.Error())
}

