func (s *Service) RecordHandlingCheckpoint(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam); err != nil {
		return nil, err
	}
	idem := str(body["idempotencyKey"])
	if idem == "" {
		return nil, models.BadRequest("idempotency_required", "required")
	}
	reqHash := hashReq(body)
	sampleID, _ := uuid.Parse(str(body["sampleId"]))
	aid, _ := uuid.Parse(str(body["assignmentId"]))
	container := str(body["containerType"])
	temp, _ := toFloat(body["observedTemperatureC"])
	recordedAt, err := parseTime(body["recordedAt"])
	if err != nil {
		return nil, models.BadRequest("invalid_time", "invalid")
	}
	sample, err := s.getSample(ctx, sampleID)
	if err != nil {
		return nil, err
	}
	if sample.CurrentHolderID == nil || *sample.CurrentHolderID != auth.User.ID {
		return nil, models.Forbidden("forbidden", "not holder")
	}
	compliant := temp >= sample.TemperatureMinC && temp <= sample.TemperatureMaxC
	if container != sample.ContainerType && container != "" {
		// soft check
	}
	cpID := uuid.New()
	var locID *uuid.UUID
	if v := str(body["locationId"]); v != "" {
		if id, err := uuid.Parse(v); err == nil {
			locID = &id
		}
	}
	_, _ = s.store.PG.Exec(ctx, `
		INSERT INTO handling_checkpoints(id,sample_id,assignment_id,location_id,container_type,observed_temperature_c,compliant,recorded_at,recorded_by)
		VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)`, cpID, sampleID, aid, locID, container, temp, compliant, recordedAt, auth.User.ID)
	status := sample.Status
	if !compliant {
		status = "exception"
		exc, _ := json.Marshal(map[string]any{"reason": "handling_noncompliant", "checkpointId": cpID.String()})
		_, _ = s.store.PG.Exec(ctx, `UPDATE samples SET status='exception', exception=$1::jsonb, handling_compliant=false WHERE id=$2`, exc, sampleID)
	}
	out := map[string]any{"checkpointId": cpID.String(), "sampleId": sampleID.String(), "compliant": compliant, "sampleStatus": status}
	s.SaveIdempotency(ctx, idem, auth.User.ID.String(), "handling_checkpoint", reqHash, 201, map[string]any{"data": out})
	return out, nil
}

func (s *Service) RecordWorkerLocation(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam); err != nil {
		return nil, err
	}
	aid, err := uuid.Parse(str(body["assignmentId"]))
	if err != nil {
		return nil, models.NotFound("not_found", "assignment")
	}
	coord, err := parseCoord(body["coordinate"])
	if err != nil {
		return nil, models.BadRequest("invalid_coordinate", "invalid")
	}
	seqF, ok := toFloat(body["sequence"])
	if !ok || seqF < 1 {
		return nil, models.BadRequest("invalid_json", "sequence")
	}
	seq := int(seqF)
	recordedAt, err := parseTime(body["recordedAt"])
	if err != nil {
		return nil, models.BadRequest("invalid_time", "invalid")
	}
	var workerID *uuid.UUID
	var sampleID uuid.UUID
	err = s.store.PG.QueryRow(ctx, `SELECT worker_id, sample_id FROM assignments WHERE id=$1`, aid).Scan(&workerID, &sampleID)
	if err == pgx.ErrNoRows {
		return nil, models.NotFound("not_found", "assignment")
	}
	if workerID == nil || *workerID != auth.User.ID {
		if auth.ActiveRole != models.RoleAdministrator {
			return nil, models.Forbidden("forbidden", "not your assignment")
		}
	}
	_, err = s.store.PG.Exec(ctx, `
		INSERT INTO worker_location_updates(assignment_id,worker_id,latitude,longitude,sequence,recorded_at)
		VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT (assignment_id,sequence) DO UPDATE SET latitude=$3,longitude=$4,recorded_at=$6`,
		aid, auth.User.ID, coord.Latitude, coord.Longitude, seq, recordedAt)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	_, _ = s.store.PG.Exec(ctx, `UPDATE users SET latest_lat=$1, latest_lng=$2, location_recorded_at=$3 WHERE id=$4`,
		coord.Latitude, coord.Longitude, recordedAt, auth.User.ID)
	_, _ = s.store.PG.Exec(ctx, `UPDATE samples SET latest_lat=$1, latest_lng=$2, location_recorded_at=$3 WHERE id=$4`,
		coord.Latitude, coord.Longitude, recordedAt, sampleID)
	return map[string]any{
		"assignmentId": aid.String(),
		"coordinate":   coord,
		"sequence":     seq,
		"recordedAt":   formatTime(recordedAt),
	}, nil
}

func (s *Service) UpdateAssignmentProgress(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator); err != nil {
		return nil, err
	}
	idem := str(body["idempotencyKey"])
	if idem == "" {
		return nil, models.BadRequest("idempotency_required", "required")
	}
	reqHash := hashReq(body)
	aid, _ := uuid.Parse(str(body["assignmentId"]))
	status := str(body["status"])
	occurredAt, err := parseTime(body["occurredAt"])
	if err != nil {
		return nil, models.BadRequest("invalid_time", "invalid")
	}
	var sampleID uuid.UUID
	var workerID *uuid.UUID
	var aStatus string
	err = s.store.PG.QueryRow(ctx, `SELECT sample_id, worker_id, status FROM assignments WHERE id=$1`, aid).Scan(&sampleID, &workerID, &aStatus)
	if err == pgx.ErrNoRows {
		return nil, models.NotFound("not_found", "assignment")
	}
	if workerID == nil || *workerID != auth.User.ID {
		if auth.ActiveRole != models.RoleAdministrator && auth.ActiveRole != models.RoleDispatcher {
			return nil, models.Forbidden("ineligible_worker", "not assigned worker")
		}
	}
	completed := status == "completed" || status == "delivered"
	_, _ = s.store.PG.Exec(ctx, `
		UPDATE assignments SET progress_status=$1, status=CASE WHEN $2 THEN 'completed' ELSE 'in_progress' END,
		completed=$2, completed_at=CASE WHEN $2 THEN $3 ELSE completed_at END, updated_at=now() WHERE id=$4`,
		status, completed, occurredAt, aid)
	s.Timeline(ctx, &sampleID, auth.User.ID.String(), auth.ActiveRole, "update_progress", "assignment", aid.String(), true, map[string]any{"status": status})
	out := map[string]any{"assignmentId": aid.String(), "sampleId": sampleID.String(), "status": status}
	s.SaveIdempotency(ctx, idem, auth.User.ID.String(), "update_progress", reqHash, 201, map[string]any{"data": out})
	return out, nil
}

