package service

import (
	"context"
	"encoding/json"

	"lablogistics/internal/models"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
)

func (s *Service) offerPendingAssignments(ctx context.Context, sampleID uuid.UUID) {
	rows, err := s.store.PG.Query(ctx, `
		SELECT id, kind, expected_sample_type_id, node_id, laboratory_id, from_location_id, to_location_id
		FROM assignments WHERE sample_id=$1 AND status='pending' AND offered_to IS NULL ORDER BY sequence`, sampleID)
	if err != nil {
		return
	}
	defer rows.Close()
	type arow struct {
		id, kind string
		stID, nodeID, labID, fromID, toID *uuid.UUID
	}
	var list []struct {
		ID   uuid.UUID
		Kind string
		StID *uuid.UUID
		Node *uuid.UUID
		Lab  *uuid.UUID
	}
	for rows.Next() {
		var id uuid.UUID
		var kind string
		var stID, nodeID, labID, fromID, toID *uuid.UUID
		if err := rows.Scan(&id, &kind, &stID, &nodeID, &labID, &fromID, &toID); err != nil {
			continue
		}
		_ = fromID
		_ = toID
		list = append(list, struct {
			ID   uuid.UUID
			Kind string
			StID *uuid.UUID
			Node *uuid.UUID
			Lab  *uuid.UUID
		}{id, kind, stID, nodeID, labID})
	}
	for _, a := range list {
		s.offerAssignment(ctx, a.ID, a.Kind, a.StID, a.Node, a.Lab)
	}
}

func (s *Service) offerAssignment(ctx context.Context, assignmentID uuid.UUID, kind string, stID, nodeID, labID *uuid.UUID) {
	worker, err := s.pickWorker(ctx, kind, stID, nodeID, labID, assignmentID)
	if err != nil || worker == nil {
		// flag exception if collection requires qualified and none available long-term
		return
	}
	exp := nowUTC().Add(OfferTimeout)
	_, _ = s.store.PG.Exec(ctx, `
		UPDATE assignments SET offered_to=$1, offer_expires_at=$2, status='offered', updated_at=now() WHERE id=$3`,
		worker.ID, exp, assignmentID)
	s.Emit(ctx, "assignment.offered", "assignment", assignmentID.String(), "user:"+worker.ID.String(), map[string]any{
		"assignmentId": assignmentID.String(), "kind": kind,
	})
	s.Timeline(ctx, nil, "system", "system", "offer_assignment", "assignment", assignmentID.String(), true, map[string]any{
		"offeredTo": worker.ID.String(), "kind": kind,
	})
}

func (s *Service) pickWorker(ctx context.Context, kind string, stID, nodeID, labID *uuid.UUID, assignmentID uuid.UUID) (*models.User, error) {
	var role string
	switch kind {
	case "collection":
		role = models.RoleCollectionProfessional
	case "transport":
		role = models.RoleDeliveryPartner
	case "node":
		role = models.RoleNodeHandler
	case "laboratory":
		role = models.RoleLaboratoryTeam
	default:
		return nil, nil
	}
	rows, err := s.store.PG.Query(ctx, `
		SELECT id, username, password_hash, email, full_name, phone, roles, qualifications, certifications,
		       active, assigned_location_id, available, capacity_units, assignment_count,
		       decline_penalty_until, latest_lat, latest_lng, location_recorded_at
		FROM users WHERE active=true AND available=true AND $1 = ANY(roles)
		ORDER BY assignment_count ASC, created_at ASC`, role)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	now := nowUTC()
	var candidates []*models.User
	for rows.Next() {
		u, err := scanUser(rows)
		if err != nil {
			continue
		}
		if u.DeclinePenaltyUntil != nil && u.DeclinePenaltyUntil.After(now) {
			continue
		}
		// already declined this assignment?
		// node/lab must match assigned location
		if kind == "node" && nodeID != nil {
			if u.AssignedLocationID == nil || *u.AssignedLocationID != *nodeID {
				continue
			}
		}
		if kind == "laboratory" && labID != nil {
			if u.AssignedLocationID == nil || *u.AssignedLocationID != *labID {
				continue
			}
		}
		if kind == "collection" && stID != nil {
			st, err := s.getSampleType(ctx, *stID)
			if err == nil && st.QualifiedCollectorRequired {
				ok := false
				req := st.RequiredQualification
				for _, q := range u.Qualifications {
					if q == req || q == st.Name {
						ok = true
						break
					}
				}
				for _, c := range u.Certifications {
					if c.Active && (c.Code == req || c.Code == st.Name) {
						if c.ExpiresAt == nil || c.ExpiresAt.After(now) {
							ok = true
						}
					}
				}
				if !ok {
					continue
				}
			}
		}
		candidates = append(candidates, u)
	}
	if len(candidates) == 0 {
		return nil, nil
	}
	return candidates[0], nil
}

func (s *Service) expireOffers(ctx context.Context) {
	rows, err := s.store.PG.Query(ctx, `
		SELECT id, offered_to, sample_id, kind, expected_sample_type_id, node_id, laboratory_id
		FROM assignments WHERE status='offered' AND offer_expires_at < now()`)
	if err != nil {
		return
	}
	defer rows.Close()
	for rows.Next() {
		var id uuid.UUID
		var offered *uuid.UUID
		var sampleID uuid.UUID
		var kind string
		var stID, nodeID, labID *uuid.UUID
		if err := rows.Scan(&id, &offered, &sampleID, &kind, &stID, &nodeID, &labID); err != nil {
			continue
		}
		_, _ = s.store.PG.Exec(ctx, `
			UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, updated_at=now() WHERE id=$1`, id)
		if offered != nil {
			until := nowUTC().Add(DeclinePenalty)
			_, _ = s.store.PG.Exec(ctx, `UPDATE users SET decline_penalty_until=$1 WHERE id=$2`, until, *offered)
		}
		s.offerAssignment(ctx, id, kind, stID, nodeID, labID)
	}
}

func (s *Service) AcceptAssignment(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator, models.RoleDispatcher); err != nil {
		return nil, err
	}
	idem := str(body["idempotencyKey"])
	if idem == "" {
		return nil, models.BadRequest("idempotency_required", "idempotency key required")
	}
	reqHash := hashReq(body)
	if hit, _, resp, err := s.CheckIdempotency(ctx, idem, auth.User.ID.String(), "accept_assignment", reqHash); err != nil {
		return nil, err
	} else if hit {
		var m map[string]any
		_ = json.Unmarshal(resp, &m)
		if d, ok := m["data"].(map[string]any); ok {
			return d, nil
		}
	}
	aid, err := uuid.Parse(str(body["assignmentId"]))
	if err != nil {
		return nil, models.NotFound("not_found", "assignment not found")
	}
	var status string
	var offeredTo, workerID *uuid.UUID
	var sampleID uuid.UUID
	err = s.store.PG.QueryRow(ctx, `
		SELECT status, offered_to, worker_id, sample_id FROM assignments WHERE id=$1`, aid).
		Scan(&status, &offeredTo, &workerID, &sampleID)
	if err == pgx.ErrNoRows {
		return nil, models.NotFound("not_found", "assignment not found")
	}
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	if status == "accepted" || status == "in_progress" || status == "completed" {
		if workerID != nil && *workerID == auth.User.ID {
			out := map[string]any{"assignmentId": aid.String(), "workerId": auth.User.ID.String(), "status": "accepted"}
			s.SaveIdempotency(ctx, idem, auth.User.ID.String(), "accept_assignment", reqHash, 201, map[string]any{"data": out})
			return out, nil
		}
		return nil, models.Conflict("assignment_taken", "already taken")
	}
	if status != "offered" && status != "pending" {
		return nil, models.Conflict("assignment_inactive", "inactive")
	}
	if offeredTo == nil || *offeredTo != auth.User.ID {
		if auth.ActiveRole != models.RoleAdministrator && auth.ActiveRole != models.RoleDispatcher {
			return nil, models.Conflict("offer_not_offered", "not offered to you")
		}
	}
	if !auth.User.Available {
		return nil, models.Conflict("worker_unavailable", "unavailable")
	}
	_, err = s.store.PG.Exec(ctx, `
		UPDATE assignments SET status='accepted', worker_id=$1, offered_to=$1, offer_expires_at=NULL, updated_at=now() WHERE id=$2`,
		auth.User.ID, aid)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	_, _ = s.store.PG.Exec(ctx, `UPDATE users SET assignment_count = assignment_count + 1 WHERE id=$1`, auth.User.ID)
	s.Timeline(ctx, &sampleID, auth.User.ID.String(), auth.ActiveRole, "accept_assignment", "assignment", aid.String(), true, nil)
	s.Audit(ctx, auth.User.ID.String(), auth.ActiveRole, "accept_assignment", "assignment", aid.String(), true, nil)
	s.Emit(ctx, "assignment.accepted", "assignment", aid.String(), "dispatcher", map[string]any{"assignmentId": aid.String()})
	out := map[string]any{"assignmentId": aid.String(), "workerId": auth.User.ID.String(), "status": "accepted"}
	s.SaveIdempotency(ctx, idem, auth.User.ID.String(), "accept_assignment", reqHash, 201, map[string]any{"data": out})
	return out, nil
}

func (s *Service) DeclineAssignment(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam); err != nil {
		return nil, err
	}
	idem := str(body["idempotencyKey"])
	if idem == "" {
		return nil, models.BadRequest("idempotency_required", "required")
	}
	reqHash := hashReq(body)
	if hit, _, resp, err := s.CheckIdempotency(ctx, idem, auth.User.ID.String(), "decline_assignment", reqHash); err != nil {
		return nil, err
	} else if hit {
		var m map[string]any
		_ = json.Unmarshal(resp, &m)
		if d, ok := m["data"].(map[string]any); ok {
			return d, nil
		}
	}
	aid, err := uuid.Parse(str(body["assignmentId"]))
	if err != nil {
		return nil, models.NotFound("not_found", "not found")
	}
	var status string
	var offeredTo *uuid.UUID
	var sampleID uuid.UUID
	var kind string
	var stID, nodeID, labID *uuid.UUID
	err = s.store.PG.QueryRow(ctx, `
		SELECT status, offered_to, sample_id, kind, expected_sample_type_id, node_id, laboratory_id FROM assignments WHERE id=$1`, aid).
		Scan(&status, &offeredTo, &sampleID, &kind, &stID, &nodeID, &labID)
	if err == pgx.ErrNoRows {
		return nil, models.NotFound("not_found", "not found")
	}
	if offeredTo == nil || *offeredTo != auth.User.ID {
		return nil, models.Conflict("offer_not_offered", "not offered")
	}
	declinedAt := nowUTC()
	if v := str(body["declinedAt"]); v != "" {
		if t, err := parseTime(v); err == nil {
			declinedAt = t
		}
	}
	_, _ = s.store.PG.Exec(ctx, `
		UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, updated_at=now() WHERE id=$1`, aid)
	until := nowUTC().Add(DeclinePenalty)
	_, _ = s.store.PG.Exec(ctx, `UPDATE users SET decline_penalty_until=$1 WHERE id=$2`, until, auth.User.ID)

	// reoffer
	worker, _ := s.pickWorker(ctx, kind, stID, nodeID, labID, aid)
	out := map[string]any{
		"assignmentId": aid.String(),
		"status":       "pending",
		"declinedBy":   auth.User.ID.String(),
		"declinedAt":   formatTime(declinedAt),
	}
	if worker != nil {
		exp := nowUTC().Add(OfferTimeout)
		_, _ = s.store.PG.Exec(ctx, `UPDATE assignments SET offered_to=$1, offer_expires_at=$2, status='offered' WHERE id=$3`, worker.ID, exp, aid)
		out["reofferedTo"] = worker.ID.String()
	}
	s.Audit(ctx, auth.User.ID.String(), auth.ActiveRole, "decline_assignment", "assignment", aid.String(), true, nil)
	s.SaveIdempotency(ctx, idem, auth.User.ID.String(), "decline_assignment", reqHash, 201, map[string]any{"data": out})
	return out, nil
}

func (s *Service) CollectAndSeal(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleCollectionProfessional, models.RoleAdministrator); err != nil {
		return nil, err
	}
	idem := str(body["idempotencyKey"])
	if idem == "" {
		return nil, models.BadRequest("idempotency_required", "required")
	}
	reqHash := hashReq(body)
	if hit, _, resp, err := s.CheckIdempotency(ctx, idem, auth.User.ID.String(), "collect_and_seal", reqHash); err != nil {
		return nil, err
	} else if hit {
		var m map[string]any
		_ = json.Unmarshal(resp, &m)
		if d, ok := m["data"].(map[string]any); ok {
			return d, nil
		}
	}
	sampleID, err := uuid.Parse(str(body["sampleId"]))
	if err != nil {
		return nil, models.NotFound("not_found", "sample")
	}
	aid, err := uuid.Parse(str(body["assignmentId"]))
	if err != nil {
		return nil, models.NotFound("not_found", "assignment")
	}
	collectedAt, err := parseTime(body["collectedAt"])
	if err != nil {
		return nil, models.BadRequest("invalid_time", "invalid collectedAt")
	}
	container := str(body["containerType"])
	temp, ok := toFloat(body["observedTemperatureC"])
	if !ok {
		return nil, models.BadRequest("invalid_json", "temperature required")
	}

	sample, err := s.getSample(ctx, sampleID)
	if err != nil {
		return nil, err
	}
	if sample.Sealed {
		return nil, models.Conflict("invalid_sample_state", "already sealed")
	}
	if collectedAt.Before(sample.EarliestCollectionAt) || collectedAt.After(sample.LatestCollectionAt) {
		return nil, models.Conflict("outside_collection_window", "outside window")
	}
	var aStatus string
	var workerID *uuid.UUID
	var kind string
	err = s.store.PG.QueryRow(ctx, `SELECT status, worker_id, kind FROM assignments WHERE id=$1 AND sample_id=$2`, aid, sampleID).
		Scan(&aStatus, &workerID, &kind)
	if err == pgx.ErrNoRows {
		return nil, models.NotFound("not_found", "assignment")
	}
	if kind != "collection" {
		return nil, models.Conflict("collection_not_ready", "not collection")
	}
	if aStatus != "accepted" && aStatus != "in_progress" {
		return nil, models.Conflict("assignment_inactive", "not accepted")
	}
	if workerID == nil || *workerID != auth.User.ID {
		if auth.ActiveRole != models.RoleAdministrator {
			return nil, models.Forbidden("forbidden", "not your assignment")
		}
	}
	// certification check
	st, _ := s.getSampleType(ctx, sample.SampleTypeID)
	if st != nil && st.QualifiedCollectorRequired {
		ok := false
		for _, q := range auth.User.Qualifications {
			if q == st.RequiredQualification || q == st.Name {
				ok = true
			}
		}
		for _, c := range auth.User.Certifications {
			if c.Active && (c.Code == st.RequiredQualification || c.Code == st.Name) {
				ok = true
			}
		}
		if !ok {
			return nil, models.Conflict("certification_inactive", "missing certification")
		}
	}
	compliant := true
	if st != nil {
		if container != "" && st.ContainerType != "" && container != st.ContainerType && container != sample.ContainerType {
			// allow if matches sample required container
			if container != sample.ContainerType {
				compliant = false
			}
		}
		if temp < sample.TemperatureMinC || temp > sample.TemperatureMaxC {
			compliant = false
		}
	}
	sealedAt := collectedAt
	_, err = s.store.PG.Exec(ctx, `
		UPDATE samples SET sealed=true, sealed_at=$1, status='sealed', current_holder_id=$2, handling_compliant=$3,
		container_type=COALESCE(NULLIF($4,''), container_type), updated_at=now() WHERE id=$5`,
		sealedAt, auth.User.ID, compliant, container, sampleID)
	if err != nil {
		return nil, models.Internal(err.Error())
	}
	_, _ = s.store.PG.Exec(ctx, `UPDATE assignments SET status='completed', completed=true, completed_at=$1, progress_status='completed', updated_at=now() WHERE id=$2`, sealedAt, aid)
	if !compliant {
		exc, _ := json.Marshal(map[string]any{"reason": "handling_noncompliant", "temperature": temp, "container": container})
		_, _ = s.store.PG.Exec(ctx, `UPDATE samples SET status='exception', exception=$1::jsonb WHERE id=$2`, exc, sampleID)
	}
	s.Timeline(ctx, &sampleID, auth.User.ID.String(), auth.ActiveRole, "collect_and_seal", "sample", sampleID.String(), true, map[string]any{"compliant": compliant})
	s.Audit(ctx, auth.User.ID.String(), auth.ActiveRole, "collect_and_seal", "sample", sampleID.String(), true, nil)
	out := map[string]any{
		"sampleId":           sampleID.String(),
		"status":             "sealed",
		"currentHolderId":    auth.User.ID.String(),
		"sealedAt":           formatTime(sealedAt),
		"handlingCompliant":  compliant,
	}
	s.SaveIdempotency(ctx, idem, auth.User.ID.String(), "collect_and_seal", reqHash, 201, map[string]any{"data": out})
	// offer next transport
	go s.offerPendingAssignments(context.Background(), sampleID)
	return out, nil
}

func (s *Service) getSample(ctx context.Context, id uuid.UUID) (*models.Sample, error) {
	var sm models.Sample
	var incomp []uuid.UUID
	var exc []byte
	err := s.store.PG.QueryRow(ctx, `
		SELECT id,request_id,requester_id,sample_type_id,origin_lat,origin_lng,origin_type,origin_node_id,
		requested_at,delivery_deadline,earliest_collection_at,latest_collection_at,container_type,temperature_min_c,temperature_max_c,
		incompatible_sample_types,status,serviceability,serviceability_reason,sealed,sealed_at,current_holder_id,active_journey_id,
		target_laboratory_id,received_laboratory_id,pending_handoff_id,exception,latest_lat,latest_lng,location_recorded_at,handling_compliant
		FROM samples WHERE id=$1`, id).Scan(
		&sm.ID, &sm.RequestID, &sm.RequesterID, &sm.SampleTypeID, &sm.OriginLat, &sm.OriginLng, &sm.OriginType, &sm.OriginNodeID,
		&sm.RequestedAt, &sm.DeliveryDeadline, &sm.EarliestCollectionAt, &sm.LatestCollectionAt, &sm.ContainerType, &sm.TemperatureMinC, &sm.TemperatureMaxC,
		&incomp, &sm.Status, &sm.Serviceability, &sm.ServiceabilityReason, &sm.Sealed, &sm.SealedAt, &sm.CurrentHolderID, &sm.ActiveJourneyID,
		&sm.TargetLaboratoryID, &sm.ReceivedLaboratoryID, &sm.PendingHandoffID, &exc, &sm.LatestLat, &sm.LatestLng, &sm.LocationRecordedAt, &sm.HandlingCompliant)
	if err == pgx.ErrNoRows {
		return nil, models.NotFound("not_found", "sample not found")
	}
	if err != nil {
		return nil, err
	}
	sm.IncompatibleSampleTypes = incomp
	if sm.IncompatibleSampleTypes == nil {
		sm.IncompatibleSampleTypes = []uuid.UUID{}
	}
	if len(exc) > 0 {
		_ = json.Unmarshal(exc, &sm.Exception)
	}
	return &sm, nil
}

func (s *Service) InitiateHandoff(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator); err != nil {
		return nil, err
	}
	idem := str(body["idempotencyKey"])
	if idem == "" {
		return nil, models.BadRequest("idempotency_required", "required")
	}
	reqHash := hashReq(body)
	if hit, _, resp, err := s.CheckIdempotency(ctx, idem, auth.User.ID.String(), "initiate_handoff", reqHash); err != nil {
		return nil, err
	} else if hit {
		var m map[string]any
		_ = json.Unmarshal(resp, &m)
