			return d, nil
		}
	}
	sampleID, _ := uuid.Parse(str(body["sampleId"]))
	fromA, _ := uuid.Parse(str(body["fromAssignmentId"]))
	toA, _ := uuid.Parse(str(body["toAssignmentId"]))
	receiverID, _ := uuid.Parse(str(body["receiverId"]))
