func (s *Service) ConfirmHandoff(ctx context.Context, auth *AuthContext, body map[string]any) (map[string]any, error) {
	if err := s.RequireRole(auth, models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator); err != nil {
		return nil, err
	}
	idem := str(body["idempotencyKey"])
	if idem == "" {
		return nil, models.BadRequest("idempotency_required", "required")
	}
	reqHash := hashReq(body)
	if hit, _, resp, err := s.CheckIdempotency(ctx, idem, auth.User.ID.String(), "confirm_handoff", reqHash); err != nil {
		return nil, err
	} else if hit {
		var m map[string]any
		_ = json.Unmarshal(resp, &m)
		if d, ok := m["data"].(map[string]any); ok {
			return d, nil
		}
	}
	hid, err := uuid.Parse(str(body["handoffId"]))
	if err != nil {
		return nil, models.NotFound("not_found", "handoff")
	}
	side := str(body["confirmationSide"])
	if side != "sender" && side != "receiver" {
		return nil, models.BadRequest("invalid_json", "invalid side")
	}
	confirmedAt, err := parseTime(body["confirmedAt"])
	if err != nil {
		return nil, models.BadRequest("invalid_time", "invalid time")
	}
	var h models.Handoff
	err = s.store.PG.QueryRow(ctx, `
		SELECT id,sample_id,from_assignment_id,to_assignment_id,sender_id,receiver_id,status,sender_confirmed,receiver_confirmed,initiated_at,confirmed_at
		FROM handoffs WHERE id=$1`, hid).Scan(&h.ID, &h.SampleID, &h.FromAssignmentID, &h.ToAssignmentID, &h.SenderID, &h.ReceiverID,
		&h.Status, &h.SenderConfirmed, &h.ReceiverConfirmed, &h.InitiatedAt, &h.ConfirmedAt)
	if err == pgx.ErrNoRows {
		return nil, models.NotFound("not_found", "handoff")
	}
	if side == "sender" {
		if auth.User.ID != h.SenderID && auth.ActiveRole != models.RoleAdministrator {
			return nil, models.Forbidden("forbidden", "not sender")
		}
		h.SenderConfirmed = true
		_, _ = s.store.PG.Exec(ctx, `UPDATE handoffs SET sender_confirmed=true WHERE id=$1`, hid)
	} else {
		if auth.User.ID != h.ReceiverID && auth.ActiveRole != models.RoleAdministrator {
			return nil, models.Forbidden("forbidden", "not receiver")
		}
		h.ReceiverConfirmed = true
		_, _ = s.store.PG.Exec(ctx, `UPDATE handoffs SET receiver_confirmed=true WHERE id=$1`, hid)
	}
	// re-read
	_ = s.store.PG.QueryRow(ctx, `SELECT sender_confirmed, receiver_confirmed FROM handoffs WHERE id=$1`, hid).Scan(&h.SenderConfirmed, &h.ReceiverConfirmed)
	holder := h.SenderID
	status := "pending"
	if h.SenderConfirmed && h.ReceiverConfirmed {
		status = "confirmed"
		holder = h.ReceiverID
		_, _ = s.store.PG.Exec(ctx, `UPDATE handoffs SET status='confirmed', confirmed_at=$1 WHERE id=$2`, confirmedAt, hid)
		_, _ = s.store.PG.Exec(ctx, `UPDATE samples SET current_holder_id=$1, pending_handoff_id=NULL, status='in_transit', updated_at=now() WHERE id=$2`, holder, h.SampleID)
		_, _ = s.store.PG.Exec(ctx, `UPDATE assignments SET status='completed', completed=true, completed_at=$1 WHERE id=$2 AND completed=false`, confirmedAt, h.FromAssignmentID)
		_, _ = s.store.PG.Exec(ctx, `UPDATE assignments SET status='accepted', worker_id=$1 WHERE id=$2 AND status IN ('pending','offered','accepted')`, holder, h.ToAssignmentID)
		s.Timeline(ctx, &h.SampleID, auth.User.ID.String(), auth.ActiveRole, "confirm_handoff", "handoff", hid.String(), true, map[string]any{"holder": holder.String()})
	}
	out := map[string]any{
		"handoffId":          hid.String(),
		"status":             status,
		"senderConfirmed":    h.SenderConfirmed,
		"receiverConfirmed":  h.ReceiverConfirmed,
		"currentHolderId":    holder.String(),
	}
	s.SaveIdempotency(ctx, idem, auth.User.ID.String(), "confirm_handoff", reqHash, 201, map[string]any{"data": out})
	return out, nil
}

