:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  color: #0f172a;
  background: #f1f5f9;
}
* { box-sizing: border-box; }
body { margin: 0; }
button, input, select, textarea {
  font: inherit;
}
.app-shell { min-height: 100vh; display: flex; flex-direction: column; }
.topbar {
  background: #0f766e; color: white; padding: 0.75rem 1.25rem;
  display: flex; gap: 1rem; align-items: center; justify-content: space-between;
}
.topbar h1 { font-size: 1.1rem; margin: 0; font-weight: 600; }
.panel {
  background: white; border-radius: 10px; padding: 1rem;
  box-shadow: 0 1px 3px rgba(0,0,0,.08); margin-bottom: 1rem;
}
.layout { display: grid; grid-template-columns: 320px 1fr; gap: 1rem; padding: 1rem; }
@media (max-width: 900px) { .layout { grid-template-columns: 1fr; } }
.nav { display: flex; flex-direction: column; gap: .4rem; }
.nav button {
  text-align: left; padding: .6rem .8rem; border: 1px solid #cbd5e1;
  background: white; border-radius: 8px; cursor: pointer;
}
.nav button.active, .nav button:hover { background: #ccfbf1; border-color: #0f766e; }
.login-wrap {
  max-width: 420px; margin: 4rem auto; background: white; padding: 2rem;
  border-radius: 12px; box-shadow: 0 8px 24px rgba(0,0,0,.08);
}
label { display: block; font-size: .85rem; margin-bottom: .25rem; color: #334155; }
input, select, textarea {
  width: 100%; padding: .55rem .7rem; border: 1px solid #cbd5e1; border-radius: 8px; margin-bottom: .75rem;
}
button.primary {
  background: #0f766e; color: white; border: none; border-radius: 8px; padding: .6rem 1rem; cursor: pointer;
}
button.secondary {
  background: #e2e8f0; border: none; border-radius: 8px; padding: .55rem .9rem; cursor: pointer;
}
.error { color: #b91c1c; background: #fef2f2; padding: .6rem .8rem; border-radius: 8px; margin-bottom: .75rem; }
.success { color: #166534; background: #f0fdf4; padding: .6rem .8rem; border-radius: 8px; margin-bottom: .75rem; }
.badge {
  display: inline-block; padding: .15rem .5rem; border-radius: 999px; font-size: .75rem; background: #e2e8f0;
}
.badge.stale { background: #fee2e2; color: #991b1b; }
.badge.fresh { background: #dcfce7; color: #166534; }
.badge.exception { background: #ffedd5; color: #9a3412; }
.table { width: 100%; border-collapse: collapse; font-size: .9rem; }
.table th, .table td { border-bottom: 1px solid #e2e8f0; padding: .5rem; text-align: left; vertical-align: top; }
#map { height: 420px; border-radius: 10px; overflow: hidden; border: 1px solid #cbd5e1; }
.timeline { list-style: none; padding: 0; margin: 0; }
.timeline li { padding: .5rem 0; border-bottom: 1px solid #f1f5f9; font-size: .9rem; }
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: .75rem; }
.muted { color: #64748b; font-size: .85rem; }
.role-switch { display: flex; gap: .5rem; align-items: center; flex-wrap: wrap; }
.role-switch select { width: auto; margin: 0; }
.monitor-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: .75rem; }
.monitor-card h3 { margin: 0 0 .5rem; font-size: .95rem; }
.monitor-card { background: #f8fafc; border-radius: 8px; padding: .75rem; border: 1px solid #e2e8f0; }
.work-tabs { display: flex; gap: .5rem; margin-bottom: .75rem; }
.work-tabs button { border: 1px solid #cbd5e1; background: white; border-radius: 999px; padding: .35rem .8rem; cursor: pointer; }
.work-tabs button.active { background: #0f766e; color: white; border-color: #0f766e; }

