export type Session = {
  sessionToken: string;
  userId: string;
  roles: string[];
  activeRole: string;
};

const TOKEN_KEY = 'lab_session_token';

export function getToken(): string | null {
  return localStorage.getItem(TOKEN_KEY);
}

export function setToken(token: string | null) {
  if (token) localStorage.setItem(TOKEN_KEY, token);
  else localStorage.removeItem(TOKEN_KEY);
}

export class ApiError extends Error {
  code: string;
  status: number;
  constructor(status: number, code: string, message: string) {
    super(message);
    this.status = status;
    this.code = code;
  }
}

export async function api<T = any>(path: string, opts: RequestInit = {}): Promise<T> {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    ...(opts.headers as Record<string, string> | undefined),
  };
  const token = getToken();
  if (token) headers['Authorization'] = `Bearer ${token}`;
  const res = await fetch(path, { ...opts, headers });
  const text = await res.text();
  let body: any = null;
  try { body = text ? JSON.parse(text) : null; } catch { body = { error: text }; }
  if (!res.ok) {
    throw new ApiError(res.status, body?.code || 'error', body?.error || res.statusText);
  }
  return body?.data !== undefined ? body.data : body;
}

export function login(username: string, password: string) {
  return api<Session>('/api/authenticate-user', {
    method: 'POST',
    body: JSON.stringify({ username, password }),
  });
}

export function selectRole(role: string) {
  return api<{ activeRole: string; roles: string[] }>('/api/select-active-role', {
    method: 'POST',
    body: JSON.stringify({ role }),
  });
}

export function bootstrap() {
  return api('/api/ui/bootstrap');
}

