  const [coord, setCoord] = useState({ lat: '12.97', lng: '77.59' });

  async function refresh() {
    const d = await api('/api/list-role-work', { method: 'POST', body: JSON.stringify({ role }) });
    setData(d);
  }

  useEffect(() => {
    refresh().catch((e) => setErr(e.message));
  }, [role]);

  async function accept(assignmentId: string) {
    setErr('');
    setMsg('');
    try {
      const res = await api('/api/accept-assignment', {
        method: 'POST',
        body: JSON.stringify({ assignmentId, idempotencyKey: crypto.randomUUID() }),
      });
      setMsg(`Accepted ${res.assignmentId}`);
      await refresh();
    } catch (e: any) {
      setErr(e.message);
    }
  }

  async function recordLocation(assignmentId: string) {
    setErr('');
    try {
      await api('/api/record-worker-location', {
        method: 'POST',
        body: JSON.stringify({
          assignmentId,
          coordinate: { latitude: parseFloat(coord.lat), longitude: parseFloat(coord.lng) },
          sequence: 1,
          recordedAt: new Date().toISOString(),
        }),
      });
      setMsg('Location recorded');
      await refresh();
    } catch (e: any) {
      setErr(e.message);
    }
  }

  const offered = [...(data.pending || []), ...(data.inProgress || [])];

  return (
    <div className="panel" aria-label="assignments">
      <h2>Assignments</h2>
      {err && <div className="error">{err}</div>}
      {msg && <div className="success" aria-label="assignment success">{msg}</div>}
      <div className="grid-2">
        <div>
          <label>Location lat</label>
          <input aria-label="Worker latitude" value={coord.lat} onChange={(e) => setCoord({ ...coord, lat: e.target.value })} />
        </div>
        <div>
          <label>Location lng</label>
          <input aria-label="Worker longitude" value={coord.lng} onChange={(e) => setCoord({ ...coord, lng: e.target.value })} />
        </div>
      </div>
      <table className="table">
        <thead>
          <tr>
            <th>Assignment</th>
            <th>Kind</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {offered.map((a: any) => (
            <tr key={a.assignmentId}>
              <td>{a.assignmentId}</td>
              <td>{a.kind}</td>
              <td>{a.status}</td>
              <td style={{ display: 'flex', gap: '.4rem' }}>
                {(a.status === 'offered' || a.status === 'pending') && (
                  <button className="primary" onClick={() => accept(a.assignmentId)} aria-label={`Accept assignment ${a.assignmentId}`}>
                    Accept
                  </button>
                )}
                <button className="secondary" onClick={() => recordLocation(a.assignmentId)} aria-label={`Record location for ${a.assignmentId}`}>
                  Record location
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
