import React, { useEffect, useMemo, useState } from 'react';
import { ApiError, api, bootstrap, getToken, login, selectRole, setToken, Session } from './api';
import { MapView } from './MapView';

type Page =
  | 'work'
  | 'request'
  | 'serviceability'
  | 'sample'
  | 'monitor'
  | 'audit'
  | 'map'
  | 'capacity'
  | 'assignments';

const ROLE_LABELS: Record<string, string> = {
  administrator: 'Administrator',
  dispatcher: 'Dispatcher',
  requester: 'Requester',
  collection_professional: 'Collection Professional',
  delivery_partner: 'Relay Courier',
  node_handler: 'Node Handler',
  laboratory_team: 'Laboratory Intake',
};

export default function App() {
  const [session, setSession] = useState<Session | null>(null);
  const [boot, setBoot] = useState<any>(null);
  const [page, setPage] = useState<Page>('work');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = getToken();
    if (!token) {
      setLoading(false);
      return;
    }
    bootstrap()
      .then((b) => {
        setBoot(b);
        setSession({
          sessionToken: token,
          userId: b.user.userId,
          roles: b.user.roles,
          activeRole: b.user.activeRole || '',
        });
      })
      .catch(() => setToken(null))
      .finally(() => setLoading(false));
  }, []);

  async function refreshBoot() {
    const b = await bootstrap();
    setBoot(b);
    return b;
  }

  async function onLogin(username: string, password: string) {
    setError('');
    try {
      const s = await login(username, password);
      setToken(s.sessionToken);
      setSession(s);
      const b = await bootstrap();
      setBoot(b);
      if (b.user.roleSelectionRequired || !s.activeRole) setPage('work');
    } catch (e: any) {
      setError(e?.message || 'Login failed');
      throw e;
    }
  }

  function signOut() {
    setToken(null);
    setSession(null);
    setBoot(null);
    setPage('work');
  }

  async function onSelectRole(role: string) {
    const res = await selectRole(role);
    setSession((s) => (s ? { ...s, activeRole: res.activeRole } : s));
    await refreshBoot();
  }

  if (loading) return <div className="login-wrap">Loading…</div>;
  if (!session) return <LoginView onLogin={onLogin} error={error} />;

  const roleRequired = !session.activeRole || boot?.user?.roleSelectionRequired;

  return (
    <div className="app-shell">
      <header className="topbar">
        <h1>Lab Sample Pickup & Delivery</h1>
        <div className="role-switch">
          <span className="muted" style={{ color: '#ccfbf1' }}>
            {boot?.user?.fullName || boot?.user?.username || session.userId}
          </span>
          <label htmlFor="role-switch" style={{ color: 'white', margin: 0 }}>
            Active role
          </label>
          <select
            id="role-switch"
            aria-label="Active role"
            value={session.activeRole || ''}
            onChange={(e) => onSelectRole(e.target.value)}
          >
            <option value="" disabled>
              Select role…
            </option>
            {session.roles.map((r) => (
              <option key={r} value={r}>
                {ROLE_LABELS[r] || r}
              </option>
            ))}
          </select>
          <button className="secondary" onClick={signOut} aria-label="Sign out">
            Sign out
          </button>
        </div>
      </header>

      {roleRequired ? (
        <div className="login-wrap">
          <h2>Select your working role</h2>
          <p className="muted">Permissions and work views use the role you select. Switching does not change your account roles.</p>
          <select
            aria-label="Active role"
            value={session.activeRole || ''}
            onChange={(e) => onSelectRole(e.target.value)}
          >
            <option value="">Choose role…</option>
            {session.roles.map((r) => (
              <option key={r} value={r}>
                {ROLE_LABELS[r] || r}
              </option>
            ))}
          </select>
        </div>
      ) : (
        <div className="layout">
          <aside className="panel nav">
            <NavButton active={page === 'work'} onClick={() => setPage('work')} label="My work" />
            {(session.activeRole === 'requester' || session.activeRole === 'administrator') && (
              <>
                <NavButton active={page === 'request'} onClick={() => setPage('request')} label="New collection request" />
                <NavButton active={page === 'serviceability'} onClick={() => setPage('serviceability')} label="Serviceability check" />
              </>
            )}
            <NavButton active={page === 'sample'} onClick={() => setPage('sample')} label="Sample view" />
            <NavButton active={page === 'assignments'} onClick={() => setPage('assignments')} label="Assignments" />
            {(session.activeRole === 'dispatcher' || session.activeRole === 'administrator') && (
              <>
                <NavButton active={page === 'monitor'} onClick={() => setPage('monitor')} label="Operations monitor" />
                <NavButton active={page === 'audit'} onClick={() => setPage('audit')} label="Audit trail" />
              </>
            )}
            {(session.activeRole === 'laboratory_team' || session.activeRole === 'node_handler' || session.activeRole === 'administrator') && (
              <NavButton active={page === 'capacity'} onClick={() => setPage('capacity')} label="Capacity" />
            )}
            <NavButton active={page === 'map'} onClick={() => setPage('map')} label="Live map" />
          </aside>
          <main>
            {page === 'work' && <WorkView role={session.activeRole} />}
            {page === 'request' && <RequestForm />}
            {page === 'serviceability' && <ServiceabilityForm />}
            {page === 'sample' && <SampleView />}
            {page === 'monitor' && <MonitorView />}
            {page === 'audit' && <AuditView />}
            {page === 'map' && <MapView />}
            {page === 'capacity' && <CapacityView />}
            {page === 'assignments' && <AssignmentsView role={session.activeRole} />}
          </main>
        </div>
      )}
    </div>
  );
}

function NavButton({ active, onClick, label }: { active: boolean; onClick: () => void; label: string }) {
  return (
    <button className={active ? 'active' : ''} onClick={onClick} aria-label={label}>
      {label}
    </button>
  );
}

function LoginView({ onLogin, error }: { onLogin: (u: string, p: string) => Promise<void>; error: string }) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [localError, setLocalError] = useState('');
  const [busy, setBusy] = useState(false);

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setLocalError('');
    setBusy(true);
    try {
      await onLogin(username, password);
    } catch (err: any) {
      setLocalError(err?.message || 'Invalid credentials');
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="login-wrap">
      <h2>Sign in</h2>
      <p className="muted">Lab sample pickup and delivery network</p>
      {(localError || error) && (
        <div className="error" role="alert" aria-label="login error">
          {localError || error || 'Invalid credentials'}
        </div>
      )}
      <form onSubmit={submit}>
        <label htmlFor="username">Username</label>
        <input id="username" aria-label="Username" value={username} onChange={(e) => setUsername(e.target.value)} autoComplete="username" />
        <label htmlFor="password">Password</label>
        <input id="password" type="password" aria-label="Password" value={password} onChange={(e) => setPassword(e.target.value)} autoComplete="current-password" />
        <button className="primary" type="submit" disabled={busy} aria-label="Sign in">
          {busy ? 'Signing in…' : 'Sign in'}
        </button>
      </form>
    </div>
  );
}

function WorkView({ role }: { role: string }) {
  const [tab, setTab] = useState<'pending' | 'inProgress' | 'completed'>('pending');
  const [data, setData] = useState<any>({ pending: [], inProgress: [], completed: [] });
  const [err, setErr] = useState('');

  useEffect(() => {
    api('/api/list-role-work', { method: 'POST', body: JSON.stringify({ role }) })
      .then(setData)
      .catch((e) => setErr(e.message));
  }, [role]);

  const items = data[tab] || [];

  return (
    <div className="panel">
      <h2>My work — {ROLE_LABELS[role] || role}</h2>
      <p className="muted">Current and past work for the selected role</p>
      {err && <div className="error">{err}</div>}
      <div className="work-tabs" role="tablist" aria-label="Work status tabs">
        {(['pending', 'inProgress', 'completed'] as const).map((t) => (
          <button key={t} className={tab === t ? 'active' : ''} onClick={() => setTab(t)} aria-label={t === 'inProgress' ? 'In progress work' : `${t} work`}>
            {t === 'inProgress' ? 'In progress' : t[0].toUpperCase() + t.slice(1)} ({(data[t] || []).length})
          </button>
        ))}
      </div>
      <table className="table" aria-label={`${tab} work table`}>
        <thead>
          <tr>
            <th>Kind</th>
            <th>ID</th>
            <th>Status</th>
            <th>History</th>
          </tr>
        </thead>
        <tbody>
          {items.length === 0 && (
            <tr>
              <td colSpan={4} className="muted">
                No items
              </td>
            </tr>
          )}
          {items.map((it: any, idx: number) => (
            <tr key={idx}>
              <td>{it.kind}</td>
              <td>{it.sampleId || it.assignmentId || it.journeyId}</td>
              <td>
                <span className="badge">{it.status}</span>
                {it.locationStale ? <span className="badge stale"> stale location</span> : it.locationStale === false ? <span className="badge fresh"> fresh</span> : null}
              </td>
              <td>
                <ol className="timeline" aria-label="status timeline">
                  {(it.history || []).map((h: any) => (
                    <li key={h.eventId}>
                      {h.action} · {h.occurredAt}
                    </li>
                  ))}
                </ol>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function RequestForm() {
  const [form, setForm] = useState({
    originLat: '12.9716',
    originLng: '77.5946',
    originType: 'home',
    sampleTypeId: '',
    containerType: 'standard',
    temperatureMinC: '2',
    temperatureMaxC: '25',
    requestedAt: new Date().toISOString(),
    deliveryDeadline: new Date(Date.now() + 6 * 3600_000).toISOString(),
    earliestCollectionAt: new Date().toISOString(),
    latestCollectionAt: new Date(Date.now() + 3 * 3600_000).toISOString(),
  });
  const [sampleTypes, setSampleTypes] = useState<any[]>([]);
  const [msg, setMsg] = useState('');
  const [err, setErr] = useState('');

  useEffect(() => {
    // bootstrap may not list sample types; fetch via serviceability snapshot / ops or create path - use read operations if admin else leave blank
    api('/api/read-operations-state', { method: 'POST', body: '{}' })
      .then(() => {})
      .catch(() => {});
    // try listing from a known endpoint - none dedicated; user pastes id. We'll try create defaults known after admin setup.
  }, []);

  function set(k: string, v: string) {
    setForm((f) => ({ ...f, [k]: v }));
  }

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setErr('');
    setMsg('');
    try {
      const body = {
        origin: { latitude: parseFloat(form.originLat), longitude: parseFloat(form.originLng) },
        originType: form.originType,
        sampleTypeId: form.sampleTypeId,
        containerType: form.containerType,
        temperatureMinC: parseFloat(form.temperatureMinC),
        temperatureMaxC: parseFloat(form.temperatureMaxC),
        requestedAt: form.requestedAt,
        deliveryDeadline: form.deliveryDeadline,
        earliestCollectionAt: form.earliestCollectionAt,
        latestCollectionAt: form.latestCollectionAt,
        idempotencyKey: crypto.randomUUID(),
      };
      const data = await api('/api/create-collection-request', { method: 'POST', body: JSON.stringify(body) });
      setMsg(`Created sample ${data.sampleId} (${data.serviceability})`);
    } catch (e: any) {
      setErr(e.message || 'Validation error');
    }
  }

  return (
    <div className="panel">
      <h2>Create collection request</h2>
      {err && (
        <div className="error" role="alert" aria-label="request validation error">
          {err}
        </div>
      )}
      {msg && <div className="success">{msg}</div>}
      <form onSubmit={submit}>
        <div className="grid-2">
          <div>
            <label>Origin latitude</label>
            <input aria-label="Origin latitude" value={form.originLat} onChange={(e) => set('originLat', e.target.value)} />
          </div>
          <div>
            <label>Origin longitude</label>
            <input aria-label="Origin longitude" value={form.originLng} onChange={(e) => set('originLng', e.target.value)} />
          </div>
        </div>
        <label>Origin type</label>
        <select aria-label="Origin type" value={form.originType} onChange={(e) => set('originType', e.target.value)}>
          <option value="home">Home</option>
          <option value="clinic">Clinic</option>
          <option value="node">Node</option>
        </select>
        <label>Sample type ID</label>
        <input aria-label="Sample type ID" value={form.sampleTypeId} onChange={(e) => set('sampleTypeId', e.target.value)} required />
        <label>Container type</label>
        <input aria-label="Container type" value={form.containerType} onChange={(e) => set('containerType', e.target.value)} />
        <div className="grid-2">
          <div>
            <label>Temp min °C</label>
            <input aria-label="Temperature min" value={form.temperatureMinC} onChange={(e) => set('temperatureMinC', e.target.value)} />
          </div>
          <div>
            <label>Temp max °C</label>
            <input aria-label="Temperature max" value={form.temperatureMaxC} onChange={(e) => set('temperatureMaxC', e.target.value)} />
          </div>
        </div>
        <label>Requested at</label>
        <input aria-label="Requested at" value={form.requestedAt} onChange={(e) => set('requestedAt', e.target.value)} />
        <label>Delivery deadline</label>
        <input aria-label="Delivery deadline" value={form.deliveryDeadline} onChange={(e) => set('deliveryDeadline', e.target.value)} />
        <label>Earliest collection</label>
        <input aria-label="Earliest collection" value={form.earliestCollectionAt} onChange={(e) => set('earliestCollectionAt', e.target.value)} />
        <label>Latest collection</label>
        <input aria-label="Latest collection" value={form.latestCollectionAt} onChange={(e) => set('latestCollectionAt', e.target.value)} />
        <button className="primary" type="submit" aria-label="Submit collection request">
          Create request
        </button>
      </form>
    </div>
  );
}

function ServiceabilityForm() {
  const [form, setForm] = useState({
    originLat: '12.9716',
    originLng: '77.5946',
    sampleTypeId: '',
    requestedAt: new Date().toISOString(),
    deliveryDeadline: new Date(Date.now() + 6 * 3600_000).toISOString(),
  });
  const [result, setResult] = useState<any>(null);
  const [err, setErr] = useState('');

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setErr('');
    setResult(null);
    try {
      const data = await api('/api/check-serviceability', {
        method: 'POST',
        body: JSON.stringify({
          origin: { latitude: parseFloat(form.originLat), longitude: parseFloat(form.originLng) },
          sampleTypeId: form.sampleTypeId,
          requestedAt: form.requestedAt,
          deliveryDeadline: form.deliveryDeadline,
        }),
      });
      setResult(data);
    } catch (e: any) {
      setErr(e.message);
    }
  }

  return (
    <div className="panel">
      <h2>Serviceability dry run</h2>
      <p className="muted">This check does not create a request, sample, journey, assignment or capacity reservation.</p>
      {err && <div className="error">{err}</div>}
      <form onSubmit={submit}>
        <div className="grid-2">
          <div>
            <label>Latitude</label>
            <input aria-label="Serviceability latitude" value={form.originLat} onChange={(e) => setForm({ ...form, originLat: e.target.value })} />
          </div>
          <div>
            <label>Longitude</label>
            <input aria-label="Serviceability longitude" value={form.originLng} onChange={(e) => setForm({ ...form, originLng: e.target.value })} />
          </div>
        </div>
        <label>Sample type ID</label>
        <input aria-label="Serviceability sample type" value={form.sampleTypeId} onChange={(e) => setForm({ ...form, sampleTypeId: e.target.value })} required />
        <label>Requested at</label>
        <input value={form.requestedAt} onChange={(e) => setForm({ ...form, requestedAt: e.target.value })} />
        <label>Delivery deadline</label>
        <input value={form.deliveryDeadline} onChange={(e) => setForm({ ...form, deliveryDeadline: e.target.value })} />
        <button className="primary" type="submit" aria-label="Check serviceability">
          Check serviceability
        </button>
      </form>
      {result && (
        <div className="success" aria-label="serviceability result">
          <div>Serviceable: {String(result.serviceable)}</div>
          <div>Reason: {result.reason}</div>
          <div>Version: {result.serviceabilityVersion}</div>
          {result.targetLaboratoryId && <div>Lab: {result.targetLaboratoryId}</div>}
          {result.estimatedArrivalAt && <div>ETA: {result.estimatedArrivalAt}</div>}
        </div>
      )}
    </div>
  );
}

function SampleView() {
  const [sampleId, setSampleId] = useState('');
  const [state, setState] = useState<any>(null);
  const [life, setLife] = useState<any>(null);
  const [err, setErr] = useState('');

  async function load(e?: React.FormEvent) {
    e?.preventDefault();
    setErr('');
    try {
      const s = await api(`/api/read-sample-state/${sampleId}`);
      setState(s);
      const l = await api('/api/read-sample-lifecycle', { method: 'POST', body: JSON.stringify({ sampleId }) });
      setLife(l);
    } catch (e: any) {
      setErr(e.message);
    }
  }

  return (
    <div className="panel">
      <h2>Sample view</h2>
      <form onSubmit={load} style={{ display: 'flex', gap: '.5rem', alignItems: 'end' }}>
        <div style={{ flex: 1 }}>
          <label>Sample ID</label>
          <input aria-label="Sample ID" value={sampleId} onChange={(e) => setSampleId(e.target.value)} />
        </div>
        <button className="primary" type="submit" aria-label="Load sample">
          Load
        </button>
      </form>
      {err && <div className="error">{err}</div>}
      {state && (
        <div aria-label="sample details">
          <p>
            Status: <span className="badge">{state.state?.status}</span>{' '}
            {state.locationStale ? <span className="badge stale" aria-label="location stale">Location stale</span> : <span className="badge fresh" aria-label="location fresh">Location fresh</span>}
            {state.state?.status === 'exception' || life?.exception ? <span className="badge exception" aria-label="exception flag">Exception</span> : null}
          </p>
          <p className="muted">
            Custodian: {life?.currentHolderId || '—'} · Progress journey: {state.activeJourneyId || '—'}
          </p>
          {state.latestLocation && (
            <p>
              Location: {state.latestLocation.latitude}, {state.latestLocation.longitude} (updated {state.locationRecordedAt || 'n/a'})
            </p>
          )}
          <h3>Ordered status history</h3>
          <ol className="timeline" aria-label="sample status history">
            {(state.timeline || []).map((t: any) => (
              <li key={t.eventId}>
                <strong>{t.action}</strong> by {t.role || t.actorId} at {t.occurredAt}
              </li>
            ))}
          </ol>
        </div>
      )}
    </div>
  );
}

function MonitorView() {
  const [ops, setOps] = useState<any>(null);
  const [err, setErr] = useState('');

  useEffect(() => {
    api('/api/read-operations-state', { method: 'POST', body: '{}' })
      .then(setOps)
      .catch((e) => setErr(e.message));
  }, []);

  if (err) return <div className="panel error">{err}</div>;
  if (!ops) return <div className="panel">Loading monitor…</div>;

  const cats = [
    { key: 'samples', label: 'Samples' },
    { key: 'workers', label: 'Workers' },
    { key: 'locations', label: 'Collection nodes' },
    { key: 'connections', label: 'Routes / connections' },
    { key: 'exceptions', label: 'Exceptions' },
    { key: 'handoffs', label: 'Handoffs' },
  ];

  return (
    <div className="panel" aria-label="operations monitor">
      <h2>Operations monitor</h2>
      <p className="muted">
        Assignment spread: {ops.assignmentCountSpread} · Ineligible assignments: {ops.ineligibleAssignmentCount}
      </p>
      <div className="monitor-grid">
        {cats.map((c) => (
          <div key={c.key} className="monitor-card" aria-label={c.label}>
            <h3>{c.label}</h3>
            <div style={{ fontSize: '1.6rem', fontWeight: 700 }}>{(ops[c.key] || []).length}</div>
            <ul className="muted">
              {(ops[c.key] || []).slice(0, 5).map((item: any, i: number) => (
                <li key={i}>{item.sampleId || item.workerId || item.name || item.connectionId || item.handoffId || JSON.stringify(item).slice(0, 40)}</li>
              ))}
            </ul>
          </div>
