function AuditView() {
  const [query, setQuery] = useState('');
  const [result, setResult] = useState<any>(null);
  const [err, setErr] = useState('');

  async function search(e?: React.FormEvent) {
    e?.preventDefault();
    setErr('');
    try {
      const data = await api('/api/search-audit-trail', {
        method: 'POST',
        body: JSON.stringify({ query, limit: 100 }),
      });
      setResult(data);
    } catch (e: any) {
      setErr(e.message);
    }
  }

  useEffect(() => {
    search();
  }, []);

  return (
    <div className="panel" aria-label="audit trail">
      <h2>Audit trail</h2>
      <form onSubmit={search} style={{ display: 'flex', gap: '.5rem' }}>
        <input aria-label="Audit search" placeholder="Search audit logs" value={query} onChange={(e) => setQuery(e.target.value)} />
        <button className="primary" type="submit" aria-label="Search audit">
          Search
        </button>
      </form>
      {err && <div className="error">{err}</div>}
      {result && (
        <table className="table" aria-label="audit results">
          <thead>
            <tr>
              <th>Time</th>
              <th>Actor</th>
              <th>Role</th>
              <th>Action</th>
              <th>Entity</th>
              <th>OK</th>
            </tr>
          </thead>
          <tbody>
            {(result.entries || []).map((e: any) => (
              <tr key={e.auditId}>
                <td>{e.occurredAt}</td>
                <td>{e.actorId}</td>
                <td>{e.role || e.actorRole}</td>
                <td>{e.action}</td>
                <td>
                  {e.entityType}:{e.entityId}
                </td>
                <td>{String(e.success)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

function CapacityView() {
  const [ops, setOps] = useState<any>(null);
  const [resourceId, setResourceId] = useState('');
  const [units, setUnits] = useState('100');
  const [cooled, setCooled] = useState('50');
  const [msg, setMsg] = useState('');
  const [err, setErr] = useState('');

  useEffect(() => {
    api('/api/read-operations-state', { method: 'POST', body: '{}' })
      .then((o) => {
        setOps(o);
        const mine = (o.locations || [])[0];
        if (mine) setResourceId(mine.locationId || mine.id);
      })
      .catch((e) => setErr(e.message));
  }, []);

  async function save(e: React.FormEvent) {
    e.preventDefault();
    setErr('');
    setMsg('');
    try {
      const data = await api('/api/configure-capacity', {
        method: 'POST',
        body: JSON.stringify({
          resourceId,
          capacityUnits: parseInt(units, 10),
          cooledCapacityUnits: parseInt(cooled, 10),
        }),
      });
      setMsg(`Updated capacity for ${data.resourceId}: ${data.capacityUnits} / cooled ${data.cooledCapacityUnits}`);
    } catch (e: any) {
      setErr(e.message);
    }
  }

  return (
    <div className="panel" aria-label="capacity configuration">
      <h2>Capacity</h2>
      <p className="muted">View and configure regular and cooled capacity at your node or laboratory.</p>
      {ops && (
        <table className="table" aria-label="my capacity">
          <thead>
            <tr>
              <th>Location</th>
              <th>Regular available</th>
              <th>Cooled available</th>
            </tr>
          </thead>
          <tbody>
            {(ops.locations || []).map((l: any) => (
              <tr key={l.locationId || l.id}>
                <td>{l.name}</td>
                <td>{l.capacity?.availableUnits ?? '—'}</td>
                <td>{l.capacity?.cooledAvailableUnits ?? '—'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
      {err && <div className="error">{err}</div>}
      {msg && <div className="success">{msg}</div>}
      <form onSubmit={save}>
        <label>Resource ID</label>
        <input aria-label="Capacity resource ID" value={resourceId} onChange={(e) => setResourceId(e.target.value)} />
        <label>Regular capacity units</label>
        <input aria-label="Regular capacity" value={units} onChange={(e) => setUnits(e.target.value)} />
        <label>Cooled capacity units</label>
        <input aria-label="Cooled capacity" value={cooled} onChange={(e) => setCooled(e.target.value)} />
        <button className="primary" type="submit" aria-label="Save capacity">
          Save capacity
        </button>
      </form>
    </div>
  );
}

function AssignmentsView({ role }: { role: string }) {
  const [data, setData] = useState<any>({ pending: [], inProgress: [], completed: [] });
  const [msg, setMsg] = useState('');
  const [err, setErr] = useState('');
  const [coord, setCoord] = useState({ lat: '12.97', lng: '77.59' });

  async function refresh() {
    const d = await api('/api/list-role-work', { method: 'POST', body: JSON.stringify({ role }) });
    setData(d);
  }

  useEffect(() => {
    refresh().catch((e) => setErr(e.message));
  }, [role]);

  async function accept(assignmentId: string) {
    setErr('');
    setMsg('');
    try {
      const res = await api('/api/accept-assignment', {
        method: 'POST',
        body: JSON.stringify({ assignmentId, idempotencyKey: crypto.randomUUID() }),
      });
      setMsg(`Accepted ${res.assignmentId}`);
      await refresh();
    } catch (e: any) {
      setErr(e.message);
    }
  }

  async function recordLocation(assignmentId: string) {
    setErr('');
    try {
      await api('/api/record-worker-location', {
        method: 'POST',
        body: JSON.stringify({
          assignmentId,
          coordinate: { latitude: parseFloat(coord.lat), longitude: parseFloat(coord.lng) },
          sequence: 1,
          recordedAt: new Date().toISOString(),
        }),
      });
      setMsg('Location recorded');
      await refresh();
    } catch (e: any) {
      setErr(e.message);
    }
  }

  const offered = [...(data.pending || []), ...(data.inProgress || [])];

  return (
    <div className="panel" aria-label="assignments">
      <h2>Assignments</h2>
      {err && <div className="error">{err}</div>}
      {msg && <div className="success" aria-label="assignment success">{msg}</div>}
      <div className="grid-2">
        <div>
          <label>Location lat</label>
          <input aria-label="Worker latitude" value={coord.lat} onChange={(e) => setCoord({ ...coord, lat: e.target.value })} />
        </div>
        <div>
          <label>Location lng</label>
          <input aria-label="Worker longitude" value={coord.lng} onChange={(e) => setCoord({ ...coord, lng: e.target.value })} />
        </div>
      </div>
      <table className="table">
        <thead>
          <tr>
            <th>Assignment</th>
            <th>Kind</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {offered.map((a: any) => (
            <tr key={a.assignmentId}>
              <td>{a.assignmentId}</td>
              <td>{a.kind}</td>
              <td>{a.status}</td>
              <td style={{ display: 'flex', gap: '.4rem' }}>
                {(a.status === 'offered' || a.status === 'pending') && (
                  <button className="primary" onClick={() => accept(a.assignmentId)} aria-label={`Accept assignment ${a.assignmentId}`}>
                    Accept
                  </button>
                )}
                <button className="secondary" onClick={() => recordLocation(a.assignmentId)} aria-label={`Record location for ${a.assignmentId}`}>
                  Record location
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

