import React, { useEffect, useRef, useState } from 'react';
import maplibregl from 'maplibre-gl';
import { Protocol } from 'pmtiles';
import { api } from './api';

export function MapView() {
  const ref = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const [err, setErr] = useState('');
  const [ops, setOps] = useState<any>(null);

  useEffect(() => {
    api('/api/read-operations-state', { method: 'POST', body: '{}' })
      .then(setOps)
      .catch(() => setOps(null));
  }, []);

  useEffect(() => {
    if (!ref.current || mapRef.current) return;

    const protocol = new Protocol();
    maplibregl.addProtocol('pmtiles', protocol.tile);

    let cancelled = false;
    (async () => {
      try {
        const style = await fetch('/map/style.json').then((r) => r.json());
        // rewrite tile sources to local pmtiles / assets
        if (style.sources) {
          for (const key of Object.keys(style.sources)) {
            const src = style.sources[key];
            if (src.url && String(src.url).includes('pmtiles')) {
              src.url = 'pmtiles:///map/bangalore.pmtiles';
            }
            if (src.tiles) {
              src.tiles = src.tiles.map((t: string) => t.replace(/^\.\//, '/map/'));
            }
          }
        }
        if (style.sprite && !String(style.sprite).startsWith('http') && !String(style.sprite).startsWith('/')) {
          style.sprite = '/map/' + String(style.sprite).replace(/^\.\//, '');
        } else if (style.sprite && String(style.sprite).startsWith('./')) {
          style.sprite = '/map/' + String(style.sprite).slice(2);
        } else if (style.sprite && !String(style.sprite).startsWith('/map') && !String(style.sprite).startsWith('http')) {
          style.sprite = '/map/sprites/sprite';
        }
        if (style.glyphs && String(style.glyphs).includes('{fontstack}')) {
          if (!String(style.glyphs).startsWith('/')) {
            style.glyphs = '/map/fonts/{fontstack}/{range}.pbf';
          }
        }

        if (cancelled) return;
        const map = new maplibregl.Map({
          container: ref.current!,
          style,
          center: [77.5946, 12.9716],
          zoom: 11,
          attributionControl: true,
        });
        map.addControl(new maplibregl.NavigationControl(), 'top-right');
        mapRef.current = map;

        map.on('load', () => {
          if (!ops) return;
          addMarkers(map, ops);
        });
      } catch (e: any) {
        // fallback bare style using local pmtiles
        try {
          const map = new maplibregl.Map({
            container: ref.current!,
            style: {
              version: 8,
              sources: {
                bangalore: {
                  type: 'vector',
                  url: 'pmtiles:///map/bangalore.pmtiles',
                },
              },
              layers: [
                {
                  id: 'background',
                  type: 'background',
                  paint: { 'background-color': '#e2e8f0' },
                },
              ],
              glyphs: '/map/fonts/{fontstack}/{range}.pbf',
            },
            center: [77.5946, 12.9716],
            zoom: 11,
          });
          mapRef.current = map;
        } catch (e2: any) {
          setErr(e2.message || e.message);
        }
      }
    })();

    return () => {
      cancelled = true;
      mapRef.current?.remove();
      mapRef.current = null;
      maplibregl.removeProtocol('pmtiles');
    };
  }, []);

  useEffect(() => {
    if (mapRef.current && ops && mapRef.current.isStyleLoaded()) {
      addMarkers(mapRef.current, ops);
    }
  }, [ops]);

  return (
    <div className="panel" aria-label="live map">
      <h2>Live map</h2>
      <p className="muted">Local PMTiles only — routes, nodes, laboratories and worker locations.</p>
      {err && <div className="error">{err}</div>}
      <div id="map" ref={ref} aria-label="map canvas" />
    </div>
  );
}

function addMarkers(map: maplibregl.Map, ops: any) {
  for (const l of ops.locations || []) {
    const c = l.coordinate;
    if (!c) continue;
    const el = document.createElement('div');
    el.style.width = '12px';
    el.style.height = '12px';
    el.style.borderRadius = '50%';
    el.style.background = l.functions?.laboratory ? '#dc2626' : '#0f766e';
    el.style.border = '2px solid white';
    el.title = l.name;
    new maplibregl.Marker({ element: el }).setLngLat([c.longitude, c.latitude]).addTo(map);
  }
  for (const w of ops.workers || []) {
    const c = w.latestLocation || w.latest_location;
    if (!c) continue;
    const el = document.createElement('div');
    el.style.width = '10px';
    el.style.height = '10px';
    el.style.borderRadius = '2px';
    el.style.background = '#2563eb';
    el.title = w.fullName || w.workerId;
    new maplibregl.Marker({ element: el }).setLngLat([c.longitude, c.latitude]).addTo(map);
  }
  for (const s of ops.samples || []) {
    const c = s.latestLocation || s.origin;
    if (!c) continue;
    const el = document.createElement('div');
    el.style.width = '8px';
    el.style.height = '8px';
    el.style.borderRadius = '50%';
    el.style.background = '#f59e0b';
    el.title = s.sampleId;
    new maplibregl.Marker({ element: el }).setLngLat([c.longitude, c.latitude]).addTo(map);
  }
}

